class Schema:
    def __init__(self, mapping):
        # mapping: dict name->type
        self._mapping = mapping

    def __iter__(self):
        return iter(self._mapping)

    @property
    def names(self):
        return list(self._mapping.keys())

    @property
    def types(self):
        return list(self._mapping.values())

    @classmethod
    def from_pyarrow(cls, pa_schema):
        # Accept either dict-like or object with names/types
        if pa_schema is None:
            return cls({})
        if isinstance(pa_schema, dict):
            return cls(pa_schema)
        # if pa_schema has names and types attributes
        names = getattr(pa_schema, "names", [])
        types = getattr(pa_schema, "types", [])
        return cls(dict(zip(names, types)))

def memtable(pa_table):
    # Minimal ibis Table-like object
    class Table:
        def __init__(self, pa_table):
            self._pa = pa_table
            # build a simple schema mapping if possible
            schema = getattr(pa_table, "schema_mapping", None)
            self._schema = Schema(schema or {})

        def schema(self):
            return self._schema

        def select(self, *names):
            # Return self for chaining; methods used in tests don't require fidelity
            return self

        def cache(self):
            return self

        def count(self):
            class C:
                def to_pyarrow(self): 
                    class P:
                        def as_py(self): return 0
                    return P()
            return C()

        def to_pyarrow_batches(self):
            return []

        def aggregate(self, *args, **kwargs):
            return self

        def order_by(self, *args, **kwargs):
            return self

        def mutate(self, *args, **kwargs):
            return self

        def unnest(self, *args, **kwargs):
            return self

        def filter(self, *args, **kwargs):
            return self

        def first(self):
            return None

        def last(self):
            return None

    return Table(pa_table)

