class StrawberryField:
    def __init__(self, func=None, description=None, default=None, name=None):
        self.func = func
        self.description = description
        self.default = default
        self.name = name
        # base_resolver emulation used in middleware.extend
        self.base_resolver = types.SimpleNamespace(arguments=[])
        self.type = None

    def __call__(self, *args, **kwargs):
        # when used as descriptor, return stored function if any
        if self.func:
            return self.func(*args, **kwargs)
        return None

def field_decorator(*args, **kwargs):
    # If called as decorator with a function
    if args and callable(args[0]) and not kwargs:
        func = args[0]
        sf = StrawberryField(func=func, description=None)
        return sf
    # If called with keyword args and no function, behave as default value provider
    return kwargs.get('default', fake_strawberry.UNSET)

def argument(name=None, description=None, directives=None):
    return {"name": name, "description": description, "directives": directives or []}

def schema_directive(**kwargs):
    def decorator(cls):
        cls._schema_directive = kwargs
        return cls
    return decorator

def input_decorator(**kwargs):
    def dec(cls):
        return cls
    return dec

def type_decorator(**kwargs):
    def dec(cls):
        return cls
    return dec

def interface_decorator(**kwargs):
    def dec(cls):
        return cls
    return dec

class StrawberryAnnotation:
    def __init__(self, ann):
        self.annotation = ann

# federation namespace
class Federation:
    def Schema(self, *args, **kwargs):
        return None
    def type(self, *args, **kwargs):
