def test_schema_types_filters_invalid_names(monkeypatch):
    # Provide a schema with invalid Python identifier and keyword
    schema = fake_ibis.Schema({"valid": fake_ibis.expr.datatypes.Integer(), "for": fake_ibis.expr.datatypes.Integer(), "also-valid": fake_ibis.expr.datatypes.Integer()})
    # Capture warnings by forcing warnings.warn to raise as exception to ensure paths exercised
    monkeypatch.setattr('warnings.warn', lambda *a, **k: None)
    types_list = list(graphique_scalars.schema_types(schema))
    # Should only yield the valid identifier "valid" and skip "also-valid" and "for"
    assert any(name == "valid" for name, _ in types_list)
    assert all('-' not in name for name, _ in types_list)

def test_filter_to_arrow_basic_and_ne():
    # Test Filter.to_arrow with list (eq) and ne
    expr = graphique_inputs.Filter.to_arrow(age={"eq": [1, 2]})
    assert isinstance(expr, Expr)
    # Test not-equal produces 'not' wrapping an is_in
    expr2 = graphique_inputs.Filter.to_arrow(age={"ne": [3]})
    assert isinstance(expr2, Expr)
    assert expr2.op in ("not", "is_in", "and", "field", "lt", "gt")  # loosely validate structure

def test_filter_to_arrow_combined_ops():
    expr = graphique_inputs.Filter.to_arrow(a={"lt": 10, "gt": 2}, b={"eq": [5]})
    assert isinstance(expr, Expr)
    # Combined expression should be an 'and' tree
    assert expr.op in ("and", "is_in", "lt", "gt", "field")

