def test_doc_field_sets_annotations_and_returns_field(monkeypatch):
    # Define a function with UNSET default parameter to exercise doc_field argument behavior
    def sample(a: int, b: int = fake_strawberry.UNSET) -> None:
        """Sample function docstring line 1
