def test_col_field_wraps_and_returns_field_with_docstring():
    # Use col_field to wrap a simple callable and ensure it returns a strawberry.field wrapper
    def dummy(self):
        """dummy doc"""
        return 1
    wrapped = graphique_models.col_field(dummy)
    # wrapped should be a strawberry.field result (our StrawberryField when decorator used)
    # since our fake field returns StrawberryField when used as decorator directly
    # but col_field returns strawberry.field(func, description=doc)
    # which our field_decorator will produce StrawberryField
    assert isinstance(wrapped, StrawberryField) or hasattr(wrapped, 'base_resolver')

