def fake_parse_duration(value):
    # Very small parser: if contains 'P' return timedelta for days/hours, else raise
    from datetime import timedelta
    if isinstance(value, str) and value.startswith("P"):
        # interpret PnDTnHnM... very naively: support "PTnS" seconds and "P{n}D" days
        if "T" in value:
            secs = 0
            if value.startswith("PT") and value.endswith("S"):
                try:
                    secs = int(value[2:-1])
                except Exception:
                    secs = 0
            return timedelta(seconds=secs)
        else:
            # days
            try:
                days = int(value[1:-1]) if value.endswith("D") else int(value[1:])
            except Exception:
                days = 0
            return timedelta(days=days)
    raise ValueError("unsupported duration")

def fake_duration_isoformat(td):
    # very simple inverse for timedelta
    from datetime import timedelta
    if isinstance(td, timedelta):
        return "PT{}S".format(int(td.total_seconds()))
    return "P0D"

