def pa_table_from_pylist(pylist):
    # Represent as a simple object with to_pydict maybe
    class TableObj:
        def __init__(self, items):
            self._items = items
            # columns derived from keys of first dict
            self.columns = list(items[0].keys()) if items else []
        def to_pydict(self):
            return self._items
    return TableObj(pylist)

def pa_table(columns: dict):
    # Build a simple table-like object with columns attr and to_pyarrow()
    class TableObj:
        def __init__(self, cols):
            self.columns = list(cols.keys())
            self._cols = cols
        def to_pylist(self):
            # naive conversion
            length = len(next(iter(self._cols.values()))) if self._cols else 0
            out = []
            for i in range(length):
                row = {k: v[i] for k, v in self._cols.items()}
                out.append(row)
            return out
    return TableObj(columns)

def pa_array(lst):
    return list(lst)

def pa_arange(start, stop):
    return list(range(start, stop))

