class FakeFragment:
    def __init__(self, path, partition_expression, rows=0):
        self.path = path
        self.partition_expression = partition_expression
        self._rows = rows
    def count_rows(self):
        return self._rows

class FakePartitioning:
    def __init__(self, names):
        self.schema = types.SimpleNamespace(names=list(names))

class FakeDataset:
    def __init__(self, path=None, partitioning=None, fragments=None):
        self._path = path
        self.partitioning = partitioning
        self._fragments = fragments or []
    def get_fragments(self, expr=None):
        # ignore expr for simplicity; if expr is provided, mimic filtering by returning subset where expr equals fragment.partition_expression
        if expr is None:
            return list(self._fragments)
        # naive filter: return fragments where partition_expression == expr
        return [f for f in self._fragments if f.partition_expression == expr]
    def count_rows(self):
        return sum(f.count_rows() for f in self._fragments)
    def filter(self, expr):
        # return a new FakeDataset with fragments matching expr
        return FakeDataset(partitioning=self.partitioning, fragments=[f for f in self._fragments if f.partition_expression == expr])
    def take(self, indices, columns=None):
        # return a simple pa.table style object with requested columns
        # we'll return a simple dict as table
        return {'indices': indices, 'columns': columns}
    def __repr__(self):
        return f"<FakeDataset path={self._path}>"

def ds_dataset(path, partitioning=None):
    # If path is a FakeDataset already return as-is
    if isinstance(path, FakeDataset):
        return path
    # accept lists of paths etc
    return FakeDataset(path=path, partitioning=partitioning)

def ds_get_partition_keys(expr):
    # expr is something like ('expr', 'k1', 'v') or a dict in our tests; return that dict
    if isinstance(expr, dict):
        return dict(expr)
    # if expr is a tuple, construct dict
    if isinstance(expr, tuple) and len(expr) >= 3 and expr[0] == 'eq':
        return {expr[1]: expr[2]}
    return {}

