def ibis_memtable(pa_table):
    # return a simple object with columns attribute and ability to order_by, cache, select slicing
    class MemTable:
        def __init__(self, t):
            self._t = t
            self.columns = getattr(t, 'columns', [])
            self._data = getattr(t, '_items', []) if hasattr(t, '_items') else []
        def order_by(self, *args):
            return self
        def cache(self):
            return self
        def __getitem__(self, key):
            # support slices
            if isinstance(key, slice):
                return self
            return self
        def select(self, *names):
            return self
        def aggregate(self, aggs, by=None):
            return self
        def mutate(self, mapping):
            return self
        def unnest(self):
            return self
        def to_pyarrow(self):
            class P:
                def as_py(self):
                    return 1
            return P()
        def to_list(self):
            return []
        def to_pyarrow_batches(self):
            return []
    return MemTable(pa_table)

