class FakeDuration:
    def __init__(self, years=0, months=0, days=0, seconds=0, microseconds=0):
        self.years = years
        self.months = months
        self.days = days
        self.seconds = seconds
        self.microseconds = microseconds
def isodate_parse_duration(s):
    # If 'Y' or 'M' in date part (before 'T'), return FakeDuration with months set to non-zero
    date_part = s.partition('T')[0]
    if 'Y' in date_part or 'M' in date_part:
        years = 0
        months = 0
        # parse simple like P1M or P1Y
        if 'Y' in date_part:
            try:
                years = int(date_part.strip('P').strip('Y'))
            except Exception:
                years = 1
        if 'M' in date_part and 'T' not in s:
            try:
                months = int(date_part.strip('P').strip('M'))
            except Exception:
                months = 1
        return FakeDuration(years=years, months=months, days=0, seconds=0, microseconds=0)
    # else return timedelta for patterns like PT1H, PT3600S or PT1S etc.
    if s.startswith('PT') and s.endswith('S'):
        try:
            sec = int(s[2:-1])
            return timedelta(seconds=sec)
        except Exception:
            return timedelta(seconds=0)
    # default fallback
    return timedelta(0)
def isodate_duration_isoformat(obj):
    if isinstance(obj, timedelta):
        total_seconds = int(obj.total_seconds())
        return f"PT{total_seconds}S"
    # handle FakeDuration
    if isinstance(obj, FakeDuration):
        months = getattr(obj, "months", 0)
        return f"P{months}M"
    raise TypeError("unsupported")
