def test_getitems_nested_access():
    nested = {"a": {"b": [0, {"c": 42}]}}
    # access a -> b -> 1 -> c
    result = graphique_core.getitems(nested, "a", "b", 1, "c")
    assert result == 42

def test_getitems_raises_on_invalid_key():
    nested = {"x": 1}
    with pytest.raises(Exception):
        # indexing into int should raise
        graphique_core.getitems(nested, "x", 0)

def test_order_key_asc_and_desc():
    # asc case
    asc_key = graphique_core.order_key("col")
    # Our fake ibis.asc returns ("asc", expr) where expr is ('_col', 'col')
    assert asc_key == ("asc", ("_col", "col"))
    # desc case with leading hyphen
    desc_key = graphique_core.order_key("-col2")
    assert desc_key == ("desc", ("_col", "col2"))

def test_scalars_parse_bigint_valid_and_invalid():
    parse = graphique_scalars.parse_bigint
    assert parse(5) == 5
    with pytest.raises(TypeError):
        parse("not-an-int")

def test_isodate_parse_duration_timelike_and_months():
    # PT1S -> timedelta 1 second
    d = sys.modules['isodate'].parse_duration("PT1S")
    assert isinstance(d, timedelta) and d.total_seconds() == 1
    # P1M -> FakeDuration with months > 0
    d2 = sys.modules['isodate'].parse_duration("P1M")
    assert hasattr(d2, "months") and d2.months == 1

def test_parse_duration_converts_months_to_MonthDayNano():
    parse = graphique_scalars.parse_duration
    # For a string that indicates months, our fake isodate returns FakeDuration -> should convert to pa.MonthDayNano
    mdn = parse("P2M")
    assert isinstance(mdn, pa.MonthDayNano)
    assert mdn.months == 2
    # For time-only durations should return timedelta
    td = parse("PT3S")
    assert isinstance(td, timedelta) and td.total_seconds() == 3

def test_duration_isoformat_overload_for_monthdaynano_and_timedelta():
    # Use the duration_isoformat function from module (single-dispatch default uses isodate)
    di = graphique_scalars.duration_isoformat
    mdn = pa.MonthDayNano([1, 2, 3_000_000_000])
    # Our registered implementation for MonthDayNano should produce a string containing 'P' (ISO format)
    s = di(mdn)
    assert isinstance(s, str) and s.startswith("P")
    # For timedelta fallback, it delegates to isodate.duration_isoformat -> PT#S
    td = timedelta(seconds=10)
    s2 = di(td)
    assert s2 == "PT10S"

def test_py_type_mapping_covering_all_types():
    py_type = graphique_scalars.py_type
    dt_mod = sys.modules['ibis.expr.datatypes']
    # Boolean -> bool
    assert py_type(dt_mod.Boolean()) is bool
    # Int64 -> BigInt NewType (int subclass)
    assert py_type(dt_mod.Int64()) == graphique_scalars.BigInt
    # Integer -> int
    assert py_type(dt_mod.Integer()) is int
    # Floating -> float
    assert py_type(dt_mod.Floating()) is float
    # Decimal -> Decimal
    assert py_type(dt_mod.Decimal()) is Decimal
    # Date -> date
    assert py_type(dt_mod.Date()) is date
    # Timestamp -> datetime
    assert py_type(dt_mod.Timestamp()) is datetime
    # Time -> time
    assert py_type(dt_mod.Time()) is time
    # Interval -> Duration NewType
