def test_schema_types_filters_invalid_identifiers_and_warns(monkeypatch):
    # Create a fake schema object that yields names and datatypes
    class FakeSchema:
        def __init__(self, mapping):
            self._map = mapping
        def __iter__(self):
            return iter(self._map.keys())
        def __getitem__(self, name):
            return self._map[name]
    # include a bad name and a good name
    mapping = {"valid_name": sys.modules['ibis.expr.datatypes'].Integer(), "9bad-name": sys.modules['ibis.expr.datatypes'].Integer()}
    fs = FakeSchema(mapping)
    # capture warnings
    with warnings.catch_warnings(record=True) as rec:
        warnings.simplefilter("always")
        items = list(graphique_scalars.schema_types(fs))
        # Should include only the valid identifier
        assert any(name == "valid_name" for name, _ in items)
        # Should have emitted a warning about invalid field name
        assert any("invalid field name" in str(w.message) for w in rec)

def test_models_selections_counts_nested_and_name_absence():
