def test_set_values_and_counts_uses_value_counts_table_shape():
    # Create a fake column that has value_counts returning a table-like object with indexable columns
    class FakeTableLike:
        def __init__(self):
            # columns produced by value_counts() in Set are expected to be indexable -> to_list
            pass
        def cache(self):
            return self
        def __getitem__(self, idx):
            # return object with to_list
            if idx == 0:
                return types.SimpleNamespace(to_list=lambda: ["a", "b"])
            return types.SimpleNamespace(to_list=lambda: [1, 2])
    class FakeColumn:
        def value_counts(self):
            return FakeTableLike()
    s = graphique_models.Set(FakeColumn(), cache=False)
    assert hasattr(s, "table")
    assert s.values() == ["a", "b"]
    assert s.counts() == [1, 2]

