def memtable(pa_table):
    # return an object with minimal API used in code: .order_by, .cache, .columns, __getitem__
    class MemTable:
        def __init__(self, table):
            self._table = table
            self.columns = list(table.keys()) if isinstance(table, dict) else getattr(table, "columns", [])
        def order_by(self, *args):
            return self
        def cache(self):
            return self
        def select(self, *args, **kwargs):
            return self
        def __getitem__(self, item):
            # emulate column access returning list-like with to_list
            class Col:
                def to_list(self):
                    return []
                def first(self):
                    return None
                def to_pyarrow(self):
                    class X:
                        def as_py(self): return 0
                    return X()
            return Col()
    return MemTable(pa_table)

