# Fake isodate module
isodate = types.ModuleType("isodate")
def parse_duration(value):
    # naive parse: if contains 'Y' or 'M' before 'T' consider months/years present
    # if contains 'M' or 'Y' return an object with years/months attributes else return timedelta
    head = value.split("T")[0]
    if "Y" in head or ("M" in head and value.startswith("P")):
        class Dur:
            def __init__(self):
                self.years = 1 if "Y" in head else 0
                self.months = 2 if "M" in head else 0
                self.days = 3
                self.seconds = 4
                self.microseconds = 500000
        return Dur()
    # default: return timedelta parsed from seconds 'PTnS' pattern
    if value.startswith("PT") and value.endswith("S"):
        secs = int(value[2:-1]) if value[2:-1] else 0
        return timedelta(seconds=secs)
    return timedelta(0)

def duration_isoformat(dur):
    # return a simple isoformat string
    if isinstance(dur, timedelta):
        return "PT0S" if dur.total_seconds() == 0 else f"PT{int(dur.total_seconds())}S"
    # for MonthDayNano-like, return with months
    months = getattr(dur, "months", 0)
    days = getattr(dur, "days", 0)
    micros = getattr(dur, "microseconds", 0)
    return f"P{months}M{days}DT{micros}U"

isodate.parse_duration = parse_duration
isodate.duration_isoformat = duration_isoformat
sys.modules["isodate"] = isodate

