def test_order_key_calls_ibis_asc_desc(monkeypatch):
    # Patch ibis._ to support __getitem__ and asc/desc to record behavior
    fake_col = object()

    class FakeIbis:
        def __init__(self):
            self._ = self

        def __getitem__(self, key):
            return f"col_{key}"

        def asc(self, arg):
