def test_parquet_filter_tries_partition_scanner(monkeypatch):
    p = core.Parquet.__new__(core.Parquet)
    p.partitioning = SimpleNamespace(schema=SimpleNamespace(names=["a"]))
    # Case 1: scanner raises ValueError -> returns None
    def ds_dataset_raise(*args, **kwargs):
        class ScannerObj:
            def scanner(self, filter=None):
                raise ValueError("bad")
        return ScannerObj()

    monkeypatch.setattr(core.ds, "dataset", ds_dataset_raise)
