def make_dummy_column():
    # Dummy ibis column-like object with required methods for tests
    class DummyRes:
        def __init__(self, value):
            self._value = value

        def to_pyarrow(self):
            class A:
                def as_py(inner_self):
                    return self._value
            return A()

    class DummyCountRes:
        def __init__(self, value):
            self._value = value

        def to_pyarrow(self):
            class A:
                def as_py(inner_self):
                    return self._value
            return A()

    class DummyColumn:
        def __init__(self):
            pass

        def type(self):
            return "DUMTYPE"

        def to_list(self):
            return [1, 2, 3]

        def count(self):
            # return object that supports to_pyarrow().as_py()
            return DummyCountRes(10)

        def nunique(self):
            return DummyCountRes(4)

        def first(self):
            class A:
                def to_pyarrow(inner_self):
                    class B:
                        def as_py(self):
                            return 1
                    return B()
            return A()

        def last(self):
            class A:
                def to_pyarrow(inner_self):
                    class B:
                        def as_py(self):
                            return 3
                    return B()
            return A()

        def value_counts(self):
            # return a table-like object with two columns accessible via [0] and [1]
            class TableLike:
                def __init__(self):
                    self._col0 = SimpleNamespace(to_list=lambda: ["a", "b"])
                    self._col1 = SimpleNamespace(to_list=lambda: [5, 6])

                def __getitem__(self, idx):
                    return [self._col0, self._col1][idx]

                def cache(self):
                    return self

            return TableLike()

        def length(self):
            return SimpleNamespace(to_list=lambda: [1, None, 3])

        def fill_null(self, value):
            return [value, value]

    return DummyColumn()


def test_column_cast_and_generic_methods(monkeypatch):
