def make_parquet_with_fragments(monkeypatch, fragments):
    """
    Helper to create a Parquet instance with a provided list of fragment-like objects.

    Each fragment is expected to be a dict-like with keys:
      - partition_expression
      - path
      - count_rows (callable returning int) or int
    """
    p = core.Parquet.__new__(core.Parquet)
    # Provide a simple partitioning schema object with names attribute
    class PartSchema:
        def __init__(self, names):
            self.names = names
    p.partitioning = types.SimpleNamespace(schema=PartSchema(["a", "b"]))
    # make get_fragments method
    def _get_fragments(expr=None):
        class Frag:
            def __init__(self, partition_expression, path, count):
                self.partition_expression = partition_expression
                self.path = path
                if callable(count):
                    self.count_rows = count
                else:
                    self.count_rows = lambda: count
        return [Frag(f["partition_expression"], f["path"], f["count"]) for f in fragments]
    p.get_fragments = _get_fragments
    return p


