def test_parquet_order_with_limit_uses_bisect_and_dataset(monkeypatch):
    # Prepare fragments with cumulative counts leading to bisect selection
    fragments = [
        {"partition_expression": {"k": 1}, "path": "p1", "count": 1},
        {"partition_expression": {"k": 2}, "path": "p2", "count": 3},
        {"partition_expression": {"k": 3}, "path": "p3", "count": 6},
    ]
