    # Replace ibis.memtable to return a FakeTable that supports expected behaviors
    class FakeColumn:
        def __init__(self, arr):
            self._arr = arr

        def cumsum(self):
            # return object with to_list
            class C:
                def __init__(self, arr):
                    self._arr = arr

                def to_list(self):
                    return self._arr
            return C(self._arr)

        def to_list(self):
            return self._arr

    class FakeSlice:
        def __init__(self, paths):
            self._paths = paths

        def __getitem__(self, key):
            if key == "__path__":
                class P:
                    def __init__(self, paths):
                        self._paths = paths

                    def to_list(self):
                        return self._paths
                return P(self._paths)
            raise KeyError

    class FakeTable:
        def __init__(self, data):
            # data is list of dicts with "__path__" and "_" keys
            self._data = data

        def order_by(self, *args):
            return self

        def cache(self):
            return self

        def __getitem__(self, item):
            # item could be "_" or slice or column
            if item == "_":
                # cumsum should reflect cumulative counts of fragments [1,3,6]
                return FakeColumn([1, 3, 6])
            if isinstance(item, slice):
                # for slice return FakeSlice with first n __path__ values
                # assume slice.start is None and slice.stop is limit
                stop = item.stop
                if stop is None:
                    stop = len(self._data)
                paths = [row["__path__"] for row in self._data[:stop]]
                return FakeSlice(paths)
            if item == "__path__":
                class P:
                    def to_list(self_inner):
                        return [row["__path__"] for row in self._data]
                return P()
            raise KeyError(item)

        def __repr__(self):
            return f"FakeTable({self._data})"

    # Build data that emulates pa.Table.from_pylist output -> pass as list to memtable
    pylist = [{"__path__": f"p{i}", "_": c} for i, c in enumerate([1, 3, 6], start=1)]
    monkeypatch.setattr(core.ibis, "memtable", lambda table: FakeTable(pylist))
    # monkeypatch ds.dataset to capture input paths and partitioning
    captured = {}
    def fake_ds_dataset(paths, partitioning=None):
        captured["paths"] = list(paths)
        captured["partitioning"] = partitioning
        return types.SimpleNamespace(paths=paths, partitioning=partitioning)
    monkeypatch.setattr(core.ds, "dataset", fake_ds_dataset)

    # Call order with limit that should pick a bisect index where cumulative >= 4 -> index 2 => +1 = 3 -> paths up to 3
    result_ds = core.Parquet.order(p, "a", limit=4)
    # ensure dataset received list of paths up to chosen limit
    assert captured["paths"] == ["p1", "p2", "p3"]
    assert isinstance(result_ds, types.SimpleNamespace)
    assert result_ds.partitioning is p.partitioning


