class TestScrubFields:
    def test_redacts_sensitive_key(self):
        data = {"password": "secret", "other": "value"}
        result = scrub_fields(data)
        assert result["password"] == "[REDACTED]"
        assert result["other"] == "value"

    def test_email_key_obfuscated(self):
        data = {"email": "test@example.com"}
        result = scrub_fields(data)
        assert result["email"] != "test@example.com"
        assert "@" in result["email"]

    def test_nested_dict(self):
        data = {"outer": {"password": "secret"}}
        result = scrub_fields(data)
        assert result["outer"]["password"] == "[REDACTED]"

    def test_list_of_dicts(self):
        data = [{"password": "a"}, {"password": "b"}]
        result = scrub_fields(data)
        assert result[0]["password"] == "[REDACTED]"
        assert result[1]["password"] == "[REDACTED]"

    def test_tuple_preserved_type(self):
        data = ({"password": "a"},)
        result = scrub_fields(data)
        assert isinstance(result, tuple)
        assert result[0]["password"] == "[REDACTED]"

    def test_set_preserved_type(self):
        data = {"a", "b"}
        result = scrub_fields(data)
        assert isinstance(result, set)
        assert result == {"a", "b"}

    def test_non_matching_value_untouched(self):
        assert scrub_fields(42) == 42
        assert scrub_fields("plain string") == "plain string"
        assert scrub_fields(None) is None

    def test_custom_field_names(self):
        data = {"custom_secret": "value"}
        result = scrub_fields(data, field_names={"custom_secret"})
        assert result["custom_secret"] == "[REDACTED]"

    def test_custom_replacement(self):
        data = {"password": "value"}
        result = scrub_fields(data, replacement="HIDDEN")
        assert result["password"] == "HIDDEN"


