class TestStringRecursiveParse:
    def test_plain_string_not_json(self):
        assert string_recursive_parse("hello") == "hello"

    def test_json_string_parsed(self):
        result = string_recursive_parse('{"a": 1}')
        assert result == {"a": 1}

    def test_json_list_string_parsed(self):
        result = string_recursive_parse("[1, 2, 3]")
        assert result == [1, 2, 3]

    def test_invalid_json_like_string_returned_as_is(self):
        result = string_recursive_parse("{not valid json")
        assert result == "{not valid json"

    def test_nested_dict(self):
        data = {"key": '{"nested": true}'}
        result = string_recursive_parse(data)
        assert result == {"key": {"nested": True}}

    def test_nested_list(self):
        data = ["plain", '{"x": 1}']
        result = string_recursive_parse(data)
        assert result == ["plain", {"x": 1}]

    def test_max_depth_reached(self):
        # build deeply nested structure exceeding _MAX_JSON_PARSE_DEPTH
        obj = '{"a": 1}'
        for _ in range(15):
            obj = {"nested": obj}
        result = string_recursive_parse(obj)
        # at some depth it should stop parsing further nested json strings
        assert isinstance(result, dict)

    def test_non_string_non_dict_non_list(self):
        assert string_recursive_parse(42) == 42
        assert string_recursive_parse(None) is None


