class TestReplaceRoutinePlaceholders:
    def test_replace_serial_placeholder(self):
        device = make_device()
        obj = {"key": "ALEXA_CURRENT_DSN"}
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "SN123"

    def test_replace_device_type_placeholder(self):
        device = make_device()
        obj = {"key": "ALEXA_CURRENT_DEVICE_TYPE"}
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "TYPE123"

    def test_replace_trigger_serial_placeholder(self):
        device = make_device()
        placeholder = (
            "<$Trigger.Alexa.Trigger.Alarms.NotificationStopped."
            "$.payload.object.device.deviceSerialNumber$>"
        )
        obj = {"key": placeholder}
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "SN123"

    def test_replace_trigger_device_type_placeholder(self):
        device = make_device()
        placeholder = (
            "<$Trigger.Alexa.Trigger.Alarms.NotificationStopped."
            "$.payload.object.device.productId$>"
        )
        obj = {"key": placeholder}
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "TYPE123"

    def test_no_replacement_needed(self):
        device = make_device()
        obj = {"key": "some_other_value"}
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "some_other_value"

    def test_nested_structure(self):
        device = make_device()
        obj = {"outer": {"inner": ["ALEXA_CURRENT_DSN", "plain"]}}
        result = replace_routine_placeholders(obj, device)
        assert result["outer"]["inner"][0] == "SN123"
        assert result["outer"]["inner"][1] == "plain"

    def test_non_string_values_preserved(self):
        device = make_device()
        obj = {"num": 42, "flag": True, "none_val": None}
        result = replace_routine_placeholders(obj, device)
        assert result["num"] == 42
        assert result["flag"] is True
        assert result["none_val"] is None


