from claude_agent_sdk import tool, SdkMcpTool


class TestToolDecorator:
    def test_dict_schema_basic(self):
        @tool("greet", "Greet a user", {"name": str})
        async def greet(args):
            return {"content": [{"type": "text", "text": f"Hello {args['name']}"}]}

        assert isinstance(greet, SdkMcpTool)
        assert greet.name == "greet"
        assert greet.description == "Greet a user"
        assert greet.input_schema == {"name": str}

    def test_typeddict_schema(self):
        from typing import TypedDict

        class MyArgs(TypedDict):
            x: int

        @tool("t1", "desc", MyArgs)
        async def handler(args):
            return {"content": []}

        assert handler.input_schema is MyArgs

    def test_non_async_handler_still_wraps(self):
        # Decorator doesn't enforce async-ness itself; just wraps.
        def sync_handler(args):
            return {"content": []}

        wrapped = tool("x", "y", {"a": int})(sync_handler)
        assert wrapped.handler is sync_handler

    def test_annotations_passed(self):
        from mcp.types import ToolAnnotations

        ann = ToolAnnotations(readOnlyHint=True)

        @tool("t", "d", {"a": int}, annotations=ann)
        async def h(args):
            return {"content": []}

        assert h.annotations is ann


