from claude_agent_sdk import _python_type_to_json_schema as py2schema


class TestPythonTypeToJsonSchema:
    def test_str(self):
        assert py2schema(str) == {"type": "string"}

    def test_int(self):
        assert py2schema(int) == {"type": "integer"}

    def test_float(self):
        assert py2schema(float) == {"type": "number"}

    def test_bool(self):
        assert py2schema(bool) == {"type": "boolean"}

    def test_optional_union(self):
        result = py2schema(str | None)
        assert result == {"type": "string"}

    def test_union_multiple(self):
        result = py2schema(int | str)
        assert "anyOf" in result

    def test_list_generic(self):
        result = py2schema(list[str])
        assert result == {"type": "array", "items": {"type": "string"}}

    def test_bare_list(self):
        assert py2schema(list) == {"type": "array"}

    def test_dict_generic(self):
        assert py2schema(dict[str, int]) == {"type": "object"}

    def test_bare_dict(self):
        assert py2schema(dict) == {"type": "object"}

    def test_unknown_type_defaults_to_string(self):
        class Weird:
            pass

        assert py2schema(Weird) == {"type": "string"}

    def test_annotated_with_description(self):
        from typing import Annotated

        result = py2schema(Annotated[str, "a description"])
        assert result == {"type": "string", "description": "a description"}

    def test_nested_typeddict(self):
        from typing import TypedDict

        class Inner(TypedDict):
            x: int

        result = py2schema(Inner)
        assert result["type"] == "object"
        assert "x" in result["properties"]

    def test_not_required_wrapper(self):
        if sys.version_info >= (3, 11):
            from typing import NotRequired
        else:
            from typing_extensions import NotRequired

        result = py2schema(NotRequired[int])
        assert result == {"type": "integer"}

    def test_required_wrapper(self):
        if sys.version_info >= (3, 11):
            from typing import Required
        else:
            from typing_extensions import Required

        result = py2schema(Required[str])
        assert result == {"type": "string"}


