from claude_agent_sdk import _typeddict_to_json_schema as td2schema


class TestTypedDictToJsonSchema:
    def test_basic_required_keys(self):
        from typing import TypedDict

        class Foo(TypedDict):
            a: int
            b: str

        result = td2schema(Foo)
        assert result["type"] == "object"
        assert result["properties"]["a"] == {"type": "integer"}
        assert result["properties"]["b"] == {"type": "string"}
        assert sorted(result["required"]) == ["a", "b"]

    def test_no_required_keys(self):
        if sys.version_info >= (3, 11):
            from typing import TypedDict, NotRequired
        else:
            from typing_extensions import TypedDict, NotRequired

        class Foo(TypedDict):
            a: NotRequired[int]

        result = td2schema(Foo)
        assert "required" not in result or result.get("required") == []

    def test_annotated_field_description(self):
        from typing import Annotated, TypedDict

        class Foo(TypedDict):
            a: Annotated[str, "the description"]

        result = td2schema(Foo)
        assert result["properties"]["a"]["description"] == "the description"


