def make_mock_transport():
    transport = MagicMock()
    transport.write = AsyncMock()
    transport.close = AsyncMock()
    transport.end_input = AsyncMock()

    async def _read_messages():
        return
        yield {}

    transport.read_messages = _read_messages
    return transport


class TestQueryInit:
    def test_default_values(self):
        transport = make_mock_transport()
        q = Query(transport=transport, is_streaming_mode=True)
        assert q.can_use_tool is None
        assert q.hooks == {}
        assert q.sdk_mcp_servers == {}
        assert q._initialize_timeout == 60.0
        assert q._agents is None
        assert q._skills is None


