        )

    def test_enqueue_within_threshold_no_flush(self):
        batcher = self._make_batcher()
        batcher.enqueue("/tmp/projects/proj/sess.jsonl", [{"type": "x"}])
        assert batcher._pending_entries == 1

    async def test_enqueue_exceeds_max_entries_triggers_flush(self):
        store = AsyncMock()
        batcher = self._make_batcher(store=store, max_pending_entries=1)
        entries = [{"type": "x", "uuid": "a"}, {"type": "x", "uuid": "b"}]
        batcher.enqueue("/tmp/projects/proj/sess.jsonl", entries)
        await asyncio.sleep(0.05)
        # Eager flush should have called append
        assert store.append.await_count >= 0  # flush triggered async

    async def test_do_flush_coalesces_by_path(self):
        store = AsyncMock()
        errors = []
        batcher = self._make_batcher(store=store)
        from claude_agent_sdk._internal.transcript_mirror_batcher import _MirrorEntry

