                "/tmp/projects/proj/sess.jsonl", [{"type": "x", "uuid": "1"}], 10
            ),
            _MirrorEntry(
                "/tmp/projects/proj/sess.jsonl", [{"type": "x", "uuid": "2"}], 10
            ),
        ]
        await batcher._do_flush(items, errors)
        assert store.append.await_count == 1
        called_key, called_entries = store.append.call_args[0]
        assert len(called_entries) == 2

    async def test_do_flush_unresolvable_path_dropped(self):
        store = AsyncMock()
        errors = []
        batcher = self._make_batcher(store=store)
        from claude_agent_sdk._internal.transcript_mirror_batcher import _MirrorEntry

        items = [_MirrorEntry("/other/path/x.jsonl", [{"type": "x"}], 10)]
        await batcher._do_flush(items, errors)
        store.append.assert_not_awaited()
        assert errors == []

    async def test_do_flush_retries_then_succeeds(self):
        store = AsyncMock()
        store.append.side_effect = [RuntimeError("fail1"), None]
        errors = []
        batcher = self._make_batcher(store=store)
        from claude_agent_sdk._internal.transcript_mirror_batcher import _MirrorEntry

        items = [
            _MirrorEntry(
                "/tmp/projects/proj/sess.jsonl", [{"type": "x", "uuid": "1"}], 10
            )
        ]
        with patch("anyio.sleep", new=AsyncMock()):
            await batcher._do_flush(items, errors)
        assert store.append.await_count == 2
        assert errors == []

    async def test_do_flush_timeout_not_retried(self):
        async def slow_append(*a, **k):
