        items = [
            _MirrorEntry(
                "/tmp/projects/proj/sess.jsonl", [{"type": "x", "uuid": "1"}], 10
            )
        ]
        await batcher._do_flush(items, errors)
        assert store.append.await_count == 1
        assert len(errors) == 1

    async def test_do_flush_all_attempts_fail_appends_error(self):
