    async def test_load_unknown_returns_none(self):
        store = InMemorySessionStore()
        assert await store.load({"project_key": "p", "session_id": "nope"}) is None

    async def test_delete_cascades_to_subkeys(self):
        store = InMemorySessionStore()
        key = {"project_key": "p", "session_id": "s"}
        sub = {**key, "subpath": "subagents/agent-1"}
        await store.append(key, [{"type": "x"}])
        await store.append(sub, [{"type": "y"}])
        await store.delete(key)
        assert await store.load(key) is None
        assert await store.load(sub) is None

    async def test_delete_targeted_subpath(self):
        store = InMemorySessionStore()
        key = {"project_key": "p", "session_id": "s"}
        sub1 = {**key, "subpath": "subagents/agent-1"}
        sub2 = {**key, "subpath": "subagents/agent-2"}
        await store.append(key, [{"type": "x"}])
        await store.append(sub1, [{"type": "y"}])
        await store.append(sub2, [{"type": "z"}])
        await store.delete(sub1)
        assert await store.load(sub1) is None
        assert await store.load(sub2) is not None
        assert await store.load(key) is not None

    async def test_monotonic_mtime_rapid_calls(self):
        store = InMemorySessionStore()
        key1 = {"project_key": "p", "session_id": "s1"}
        key2 = {"project_key": "p", "session_id": "s2"}
        with patch("time.time", return_value=1000.0):
            await store.append(key1, [{"type": "x"}])
            await store.append(key2, [{"type": "x"}])
        sessions = await store.list_sessions("p")
        mtimes = {s["session_id"]: s["mtime"] for s in sessions}
        assert mtimes["s1"] != mtimes["s2"]

    async def test_list_subkeys(self):
        store = InMemorySessionStore()
        key = {"project_key": "p", "session_id": "s"}
        await store.append(key, [{"type": "x"}])
        await store.append({**key, "subpath": "subagents/agent-1"}, [{"type": "y"}])
        subkeys = await store.list_subkeys(key)
        assert subkeys == ["subagents/agent-1"]


