from claude_agent_sdk._internal.session_summary import fold_session_summary


class TestFoldSessionSummary:
    def test_first_append_prev_none(self):
        key = {"project_key": "p", "session_id": "s"}
        result = fold_session_summary(
            None, key, [{"type": "x", "timestamp": "2024-01-01T00:00:00.000Z"}]
        )
        assert result["session_id"] == "s"
        assert result["mtime"] == 0
        assert result["data"]["created_at"] is not None

    def test_tag_empty_string_clears(self):
        key = {"project_key": "p", "session_id": "s"}
        prev = fold_session_summary(None, key, [{"type": "tag", "tag": "mytag"}])
        assert prev["data"]["tag"] == "mytag"
        result = fold_session_summary(prev, key, [{"type": "tag", "tag": ""}])
        assert "tag" not in result["data"]

    def test_first_prompt_locked_prevents_overwrite(self):
        key = {"project_key": "p", "session_id": "s"}
        entry1 = {
            "type": "user",
            "message": {"role": "user", "content": "first prompt here"},
        }
        result = fold_session_summary(None, key, [entry1])
        assert result["data"]["first_prompt"] == "first prompt here"
        assert result["data"]["first_prompt_locked"] is True
        entry2 = {
            "type": "user",
            "message": {"role": "user", "content": "second prompt should not overwrite"},
        }
        result2 = fold_session_summary(result, key, [entry2])
        assert result2["data"]["first_prompt"] == "first prompt here"

    def test_command_fallback_pattern(self):
        key = {"project_key": "p", "session_id": "s"}
        entry = {
            "type": "user",
            "message": {
                "role": "user",
                "content": "<command-name>mycommand</command-name>",
            },
        }
        result = fold_session_summary(None, key, [entry])
        assert result["data"].get("command_fallback") == "mycommand"
        assert "first_prompt_locked" not in result["data"]


