"""Test suite for nox action_helper and core utilities."""
from __future__ import annotations

import argparse
import json
import os
import sys
from unittest.mock import MagicMock, patch

import pytest

from action_helper import filter_version, valid_version, setup_action


# ---------------------------------------------------------------------------
# action_helper.filter_version
# ---------------------------------------------------------------------------

class TestFilterVersion:
    def test_simple_version(self):
        assert filter_version("3.9") == "3.9"

    def test_pypy_prefix_dash(self):
        assert filter_version("pypy-3.9") == "3.9"

    def test_pypy_prefix_no_dash(self):
        assert filter_version("pypy3.9") == "3.9"

    def test_tilde_prefix(self):
        assert filter_version("~3.9.0-0") == "3.9"

    def test_dev_suffix(self):
        assert filter_version("3.12-dev") == "3.12"

    def test_free_threaded(self):
        assert filter_version("3.13t") == "3.13t"

    def test_free_threaded_with_patch(self):
        assert filter_version("3.13.0t") == "3.13t"

    def test_full_version_truncated(self):
        assert filter_version("3.9.1") == "3.9"

    def test_invalid_missing_minor(self):
        with pytest.raises(ValueError):
            filter_version("3")

    def test_invalid_major_not_digit(self):
        with pytest.raises(ValueError):
            filter_version("x.9")

    def test_invalid_minor_not_digit(self):
        with pytest.raises(ValueError):
            filter_version("3.x")


