# ---------------------------------------------------------------------------
# action_helper.setup_action
# ---------------------------------------------------------------------------

class TestSetupAction:
    def test_basic_versions(self, capsys):
        setup_action("3.9,3.10")
        captured = capsys.readouterr()
        assert "interpreters=" in captured.out
        payload = json.loads(captured.out.split("interpreters=")[1])
        assert "3.9" in payload
        assert "3.10" in payload
        # self version added since not present
        assert "3.12" in payload

    def test_self_version_moved_to_end(self, capsys):
        setup_action("3.12,3.9")
        captured = capsys.readouterr()
        payload = json.loads(captured.out.split("interpreters=")[1])
        assert payload[-1] == "3.12"

    def test_duplicate_cpython_versions_raises(self):
        with pytest.raises(ValueError, match="multiple versions specified"):
            setup_action("3.9,3.9.1")

    def test_duplicate_pypy_versions_raises(self):
        with pytest.raises(ValueError, match="multiple versions specified"):
            setup_action("pypy3.9,pypy-3.9")

    def test_pypy_and_cpython_combined(self, capsys):
        setup_action("pypy3.9,3.10")
        captured = capsys.readouterr()
        payload = json.loads(captured.out.split("interpreters=")[1])
        assert "pypy3.9" in payload
        assert "3.10" in payload

    def test_empty_input(self, capsys):
        setup_action("")
        captured = capsys.readouterr()
        payload = json.loads(captured.out.split("interpreters=")[1])
        assert payload == ["3.12"]

    def test_whitespace_versions_filtered(self, capsys):
        setup_action(" 3.9 , , 3.10 ")
        captured = capsys.readouterr()
        payload = json.loads(captured.out.split("interpreters=")[1])
        assert "3.9" in payload
