from nox._resolver import CycleError, lazy_stable_topo_sort


class TestLazyStableTopoSort:
    def test_simple_sort(self):
        deps = {
            "a": ["c", "b"],
            "b": [],
            "c": [],
            "d": ["e"],
            "e": ["c"],
            "root": ["a", "d"],
        }
        result = list(lazy_stable_topo_sort(deps, "root", drop_root=False))
        assert result == ["c", "b", "a", "e", "d", "root"]

    def test_drop_root_default(self):
        deps = {"a": [], "root": ["a"]}
        result = list(lazy_stable_topo_sort(deps, "root"))
        assert "root" not in result
        assert result == ["a"]

    def test_no_dependencies(self):
        deps = {"root": []}
        result = list(lazy_stable_topo_sort(deps, "root"))
        assert result == []

    def test_cycle_detection(self):
        deps = {
            "a": ["b"],
            "b": ["a"],
            "root": ["a"],
        }
        with pytest.raises(CycleError):
            list(lazy_stable_topo_sort(deps, "root"))

    def test_self_cycle(self):
        deps = {"a": ["a"], "root": ["a"]}
        with pytest.raises(CycleError):
            list(lazy_stable_topo_sort(deps, "root"))

    def test_diamond_dependency(self):
        deps = {
            "a": ["c"],
            "b": ["c"],
            "c": [],
            "root": ["a", "b"],
        }
        result = list(lazy_stable_topo_sort(deps, "root"))
        assert result.index("c") < result.index("a")
        assert result.index("c") < result.index("b")


