import pytest
from voluptuous import (
    Schema, Required, Optional, Exclusive, Inclusive, Remove, Extra,
    All, Any, Length, Range, In, NotIn, Coerce, Match, Lower, Upper,
    Msg, Object, ALLOW_EXTRA, REMOVE_EXTRA, PREVENT_EXTRA,
)
from voluptuous.error import (
    Invalid, MultipleInvalid, RequiredFieldInvalid, ExclusiveInvalid,
    InclusiveInvalid, DictInvalid, SchemaError, CoerceInvalid,
    RangeInvalid, LengthInvalid, InInvalid,
)
from voluptuous.humanize import humanize_error, validate_with_humanized_errors
from voluptuous.util import DefaultTo, SetTo, Set as UtilSet, Literal


def test_basic_schema_valid():
    schema = Schema({'a': str, 'b': int})
    result = schema({'a': 'x', 'b': 1})
    assert result == {'a': 'x', 'b': 1}


def test_basic_schema_invalid_type():
    schema = Schema({'a': str})
    with pytest.raises(MultipleInvalid):
        schema({'a': 1})


def test_extra_key_prevented():
    schema = Schema({'a': str}, extra=PREVENT_EXTRA)
    with pytest.raises(MultipleInvalid):
        schema({'a': 'x', 'b': 1})


def test_extra_key_allowed():
    schema = Schema({'a': str}, extra=ALLOW_EXTRA)
    result = schema({'a': 'x', 'b': 1})
    assert result == {'a': 'x', 'b': 1}


def test_extra_key_removed():
    schema = Schema({'a': str}, extra=REMOVE_EXTRA)
    result = schema({'a': 'x', 'b': 1})
    assert result == {'a': 'x'}


def test_required_key_missing():
    schema = Schema({Required('a'): str})
    with pytest.raises(MultipleInvalid) as exc_info:
        schema({})
    assert isinstance(exc_info.value.errors[0], RequiredFieldInvalid)


def test_required_key_default():
    schema = Schema({Required('a', default='foo'): str})
    result = schema({})
    assert result == {'a': 'foo'}


def test_optional_key_missing():
    schema = Schema({Optional('a'): str})
    result = schema({})
    assert result == {}


def test_optional_key_default():
    schema = Schema({Optional('a', default='bar'): str})
    result = schema({})
    assert result == {'a': 'bar'}


def test_optional_key_default_callable():
    schema = Schema({Optional('a', default=list): list})
    result = schema({})
    assert result == {'a': []}


def test_exclusive_group_violation():
    schema = Schema({Exclusive('a', 'grp'): int, Exclusive('b', 'grp'): int})
    with pytest.raises(MultipleInvalid) as exc:
        schema({'a': 1, 'b': 2})
    assert isinstance(exc.value.errors[0], ExclusiveInvalid)


def test_exclusive_group_ok():
    schema = Schema({Exclusive('a', 'grp'): int, Exclusive('b', 'grp'): int})
    result = schema({'a': 1})
    assert result == {'a': 1}


def test_inclusive_group_violation():
    schema = Schema({Inclusive('a', 'grp'): int, Inclusive('b', 'grp'): int})
    with pytest.raises(MultipleInvalid) as exc:
        schema({'a': 1})
    assert isinstance(exc.value.errors[0], InclusiveInvalid)


def test_inclusive_group_ok_both():
    schema = Schema({Inclusive('a', 'grp'): int, Inclusive('b', 'grp'): int})
    result = schema({'a': 1, 'b': 2})
    assert result == {'a': 1, 'b': 2}


def test_inclusive_group_ok_none():
    schema = Schema({Inclusive('a', 'grp'): int, Inclusive('b', 'grp'): int})
    result = schema({})
    assert result == {}


def test_remove_marker():
    schema = Schema({str: int, Remove(int): str})
    result = schema({1: 'red', 'red': 1, 2: 'green'})
    assert result == {'red': 1}


def test_dict_not_a_dict():
    schema = Schema({'a': str})
    with pytest.raises(MultipleInvalid):
        schema([])


def test_list_schema_valid():
    schema = Schema(['one', 'two', int])
    result = schema(['one', 1])
    assert result == ['one', 1]


def test_list_schema_invalid():
    schema = Schema(['one', 'two', int])
    with pytest.raises(MultipleInvalid):
        schema([3.5])


def test_list_schema_empty_reject_nonempty():
    schema = Schema([])
    with pytest.raises(MultipleInvalid):
        schema([1])


def test_list_schema_empty_accept_empty():
    schema = Schema([])
    result = schema([])
    assert result == []


def test_tuple_schema():
    schema = Schema(('one', 'two', int))
    result = schema((1,))
    assert result == (1,)


def test_set_schema_valid():
    schema = Schema({int})
    result = schema({1, 2, 3})
    assert result == {1, 2, 3}


def test_set_schema_invalid_type():
    schema = Schema({int})
    with pytest.raises(Invalid):
        schema(42)


def test_set_schema_invalid_value():
    schema = Schema({int})
    with pytest.raises(MultipleInvalid):
        schema({'a'})


def test_any_validator():
    schema = Schema(Any('a', 'b', int))
    assert schema('a') == 'a'
    assert schema(5) == 5
    with pytest.raises(MultipleInvalid):
        schema('c')


def test_any_with_msg():
    schema = Schema(Any(1, 2, msg="expected 1 or 2"))
    with pytest.raises(MultipleInvalid, match="expected 1 or 2"):
        schema(3)


def test_all_validator():
    schema = Schema(All('10', Coerce(int)))
    assert schema('10') == 10


def test_all_invalid():
    schema = Schema(All(int, Range(min=1, max=10)))
    with pytest.raises(MultipleInvalid):
        schema(20)


def test_coerce_success():
    schema = Schema(Coerce(int))
    assert schema('5') == 5


def test_coerce_failure():
    schema = Schema(Coerce(int))
    with pytest.raises(MultipleInvalid):
        schema('abc')


def test_coerce_custom_message():
    c = Coerce(int, msg="bad")
    with pytest.raises(CoerceInvalid, match="bad"):
        c('abc')


def test_length_validator():
    schema = Schema(Length(min=2, max=4))
    assert schema('abc') == 'abc'
    with pytest.raises(MultipleInvalid):
        schema('a')
    with pytest.raises(MultipleInvalid):
        schema('abcde')


def test_range_validator():
    schema = Schema(Range(min=1, max=10))
    assert schema(5) == 5
    with pytest.raises(MultipleInvalid):
        schema(0)
    with pytest.raises(MultipleInvalid):
        schema(11)


def test_range_excluded_bounds():
    r = Range(min=1, max=10, min_included=False, max_included=False)
    with pytest.raises(RangeInvalid):
        r(1)
    with pytest.raises(RangeInvalid):
        r(10)
    assert r(5) == 5


def test_in_validator():
    schema = Schema(In([1, 2, 3]))
    assert schema(1) == 1
    with pytest.raises(MultipleInvalid):
        schema(4)


def test_notin_validator():
    schema = Schema(NotIn([1, 2, 3]))
    assert schema(4) == 4
    with pytest.raises(MultipleInvalid):
        schema(1)


def test_match_validator():
    schema = Schema(Match(r'^\d+$'))
    assert schema('123') == '123'
    with pytest.raises(MultipleInvalid):
        schema('abc')


def test_match_non_string():
    m = Match(r'^\d+$')
    with pytest.raises(Invalid, match="expected string or buffer"):
        m(123)


def test_lower_upper():
    assert Lower('HI') == 'hi'
    assert Upper('hi') == 'HI'


def test_default_to():
    d = DefaultTo(42)
    assert d(None) == 42
    assert d(5) == 5


def test_set_to():
    s = SetTo(42)
    assert s('anything') == 42


def test_util_set():
    s = UtilSet()
    result = s([1, 2, 2])
    assert result == {1, 2}


def test_util_set_invalid():
    s = UtilSet()
    with pytest.raises(Invalid):
        s([{1, 2}, {3, 4}])


def test_literal():
    lit = Literal('foo')
    assert lit('foo') == 'foo'
    with pytest.raises(Invalid):
        lit('bar')


def test_msg_validator():
    schema = Schema(Msg(['one', 'two', int], 'should be one of "one", "two" or an integer'))
    with pytest.raises(MultipleInvalid, match='should be one of'):
        schema(['three'])


def test_msg_invalid_class():
    with pytest.raises(SchemaError):
        Msg([int], 'bad', cls=KeyError)


def test_object_schema():
    class Structure:
        def __init__(self, one=None, three=None):
            self.one = one
            self.three = three

    validate = Schema(Object({'one': 'two', 'three': 'four'}, cls=Structure))
    result = validate(Structure(one='two', three='four'))
    assert result.one == 'two'


def test_object_schema_wrong_class():
    class Structure:
        pass

    class Other:
        pass

    validate = Schema(Object({}, cls=Structure))
    with pytest.raises(MultipleInvalid):
        validate(Other())


def test_schema_extend():
    base = Schema({'a': str})
    extended = base.extend({'b': int})
    result = extended({'a': 'x', 'b': 1})
    assert result == {'a': 'x', 'b': 1}


def test_schema_extend_conflict_extra():
    base = Schema({'a': str}, extra=PREVENT_EXTRA)
    ext_schema = Schema({'b': int}, extra=ALLOW_EXTRA)
    with pytest.raises(SchemaError):
        base.extend(ext_schema)


def test_schema_infer():
    data = {'foo': 1, 'bar': {'a': True}, 'baz': ['x']}
    schema = Schema.infer(data)
    result = schema({'foo': 2, 'bar': {'a': False}, 'baz': ['y']})
    assert result == {'foo': 2, 'bar': {'a': False}, 'baz': ['y']}


def test_schema_equality():
    v1 = Schema({Required('a'): str})
    v2 = Schema({Required('a'): str})
    v3 = Schema({Required('b'): str})
    assert v1 == v2
    assert v1 != v3
    assert v1 != "not a schema"


def test_schema_repr():
    s = Schema({'a': str})
    assert 'Schema' in repr(s)


def test_unsupported_schema_type():
    class Foo:
        pass
    with pytest.raises(SchemaError):
        Schema(Foo())


def test_humanize_error():
    schema = Schema({'a': int})
    try:
