def test_validate_with_humanized_errors_failure():
    from voluptuous.error import Error as VError
    schema = Schema({'a': int})
    with pytest.raises(VError):
        validate_with_humanized_errors({'a': 'bad'}, schema)


def test_invalid_error_str_and_path():
