class TestPermissionUpdate:
    def test_to_dict_add_rules(self):
        pu = PermissionUpdate(
            type="addRules",
            rules=[PermissionRuleValue(tool_name="Bash", rule_content="ls")],
            behavior="allow",
            destination="session",
        )
        d = pu.to_dict()
        assert d["type"] == "addRules"
        assert d["destination"] == "session"
        assert d["rules"] == [{"toolName": "Bash", "ruleContent": "ls"}]
        assert d["behavior"] == "allow"

    def test_to_dict_set_mode(self):
        pu = PermissionUpdate(type="setMode", mode="plan")
        d = pu.to_dict()
        assert d == {"type": "setMode", "mode": "plan"}

    def test_to_dict_add_directories(self):
        pu = PermissionUpdate(type="addDirectories", directories=["/tmp"])
        d = pu.to_dict()
        assert d == {"type": "addDirectories", "directories": ["/tmp"]}

    def test_from_dict_roundtrip(self):
        data = {
            "type": "addRules",
            "rules": [{"toolName": "Read", "ruleContent": None}],
            "behavior": "deny",
            "destination": "userSettings",
        }
        pu = PermissionUpdate.from_dict(data)
        assert pu.type == "addRules"
        assert pu.rules[0].tool_name == "Read"
        assert pu.behavior == "deny"
        assert pu.destination == "userSettings"

    def test_from_dict_no_rules(self):
        data = {"type": "setMode", "mode": "auto"}
        pu = PermissionUpdate.from_dict(data)
        assert pu.rules is None
        assert pu.mode == "auto"


