@pytest.mark.anyio
class TestInMemorySessionStore:
    async def test_append_and_load(self):
        store = InMemorySessionStore()
        key = {"project_key": "p", "session_id": "s"}
        await store.append(key, [{"type": "x", "n": 1}])
        loaded = await store.load(key)
        assert loaded == [{"type": "x", "n": 1}]

    async def test_load_missing_returns_none(self):
        store = InMemorySessionStore()
        assert await store.load({"project_key": "p", "session_id": "missing"}) is None

    async def test_append_empty_noop(self):
        store = InMemorySessionStore()
        key = {"project_key": "p", "session_id": "s"}
        await store.append(key, [{"type": "x"}])
        await store.append(key, [])
        assert await store.load(key) == [{"type": "x"}]

    async def test_list_sessions_excludes_subpaths(self):
        store = InMemorySessionStore()
        main = {"project_key": "p", "session_id": "s"}
        sub = {"project_key": "p", "session_id": "s", "subpath": "subagents/a"}
        await store.append(main, [{"type": "x"}])
        await store.append(sub, [{"type": "y"}])
        sessions = await store.list_sessions("p")
        assert [s["session_id"] for s in sessions] == ["s"]

    async def test_delete_cascades_to_subkeys(self):
        store = InMemorySessionStore()
        main = {"project_key": "p", "session_id": "s"}
        sub = {"project_key": "p", "session_id": "s", "subpath": "subagents/a"}
        await store.append(main, [{"type": "x"}])
        await store.append(sub, [{"type": "y"}])
        await store.delete(main)
        assert await store.load(main) is None
        assert await store.load(sub) is None

    async def test_delete_subpath_only_removes_target(self):
        store = InMemorySessionStore()
        main = {"project_key": "p", "session_id": "s"}
        sub1 = {"project_key": "p", "session_id": "s", "subpath": "subagents/a"}
        sub2 = {"project_key": "p", "session_id": "s", "subpath": "subagents/b"}
        await store.append(main, [{"type": "x"}])
        await store.append(sub1, [{"type": "y"}])
        await store.append(sub2, [{"type": "z"}])
        await store.delete(sub1)
        assert await store.load(sub1) is None
        assert await store.load(sub2) is not None
        assert await store.load(main) is not None

    async def test_list_subkeys(self):
        store = InMemorySessionStore()
        main = {"project_key": "p", "session_id": "s"}
        sub = {"project_key": "p", "session_id": "s", "subpath": "subagents/a"}
        await store.append(main, [{"type": "x"}])
        await store.append(sub, [{"type": "y"}])
        subkeys = await store.list_subkeys(main)
        assert subkeys == ["subagents/a"]

    def test_size_and_clear(self):
        store = InMemorySessionStore()
        assert store.size == 0
        store.clear()
        assert store._store == {}


