class TestJsonFieldExtraction:
    def test_extract_json_string_field_found(self):
        text = '{"customTitle":"hello","other":1}'
        assert _extract_json_string_field(text, "customTitle") == "hello"

    def test_extract_json_string_field_missing(self):
        text = '{"other":1}'
        assert _extract_json_string_field(text, "customTitle") is None

    def test_extract_json_string_field_with_escape(self):
        text = '{"customTitle":"he said \\"hi\\""}'
        assert _extract_json_string_field(text, "customTitle") == 'he said "hi"'

    def test_extract_last_json_string_field(self):
        text = '{"tag":"first"}\n{"tag":"second"}'
        assert _extract_last_json_string_field(text, "tag") == "second"

    def test_extract_first_prompt_from_head_basic(self):
        line = json.dumps(
            {
                "type": "user",
                "message": {"role": "user", "content": "Hello world"},
            }
        )
        head = line + "\n"
        assert _extract_first_prompt_from_head(head) == "Hello world"

    def test_extract_first_prompt_skips_tool_result(self):
        line = json.dumps(
            {
                "type": "user",
                "message": {
                    "role": "user",
                    "content": [{"type": "tool_result", "tool_use_id": "x"}],
                },
            }
        )
        head = line + "\n"
        assert _extract_first_prompt_from_head(head) == ""

    def test_extract_first_prompt_truncates_long_text(self):
        long_text = "x" * 300
        line = json.dumps(
            {"type": "user", "message": {"role": "user", "content": long_text}}
        )
        head = line + "\n"
        result = _extract_first_prompt_from_head(head)
        assert len(result) <= 201
        assert result.endswith("\u2026")

    def test_extract_first_prompt_command_fallback(self):
        line = json.dumps(
            {
                "type": "user",
                "message": {
                    "role": "user",
                    "content": "<command-name>mycmd</command-name>",
                },
            }
        )
        head = line + "\n"
        assert _extract_first_prompt_from_head(head) == "mycmd"


