class TestToolDecorator:
    def test_dict_input_schema(self):
        @tool("greet", "Greet", {"name": str})
        async def greet(args):
            return {"content": [{"type": "text", "text": "hi"}]}

        assert isinstance(greet, SdkMcpTool)
        assert greet.name == "greet"
        assert greet.input_schema == {"name": str}

    def test_typeddict_input_schema(self):
        class Schema(TypedDict):
            x: int

        @tool("t", "desc", Schema)
        async def handler(args):
            return {"content": []}

        assert handler.input_schema is Schema

    def test_json_schema_dict_passthrough(self):
        schema = {"type": "object", "properties": {"a": {"type": "string"}}}

        @tool("t2", "desc", schema)
        async def handler(args):
            return {"content": []}

        assert handler.input_schema == schema


