class TestCreateSdkMcpServer:
    def test_empty_tools_list(self):
        config = create_sdk_mcp_server(name="empty", tools=[])
        assert config["type"] == "sdk"
        assert config["name"] == "empty"

    def test_none_tools(self):
        config = create_sdk_mcp_server(name="noneserver")
        assert config["name"] == "noneserver"

    async def test_call_tool_not_found_raises(self):
        @tool("known", "d", {"x": str})
        async def known_tool(args):
            return {"content": [{"type": "text", "text": "ok"}]}

        config = create_sdk_mcp_server(name="srv", tools=[known_tool])
        server = config["instance"]

        from mcp.types import CallToolRequest

        handler = server.request_handlers.get(CallToolRequest)
        assert handler is not None

        from mcp.types import CallToolRequestParams

        req = CallToolRequest(
            method="tools/call",
            params=CallToolRequestParams(name="missing", arguments={}),
        )
        # The mcp Server's call_tool decorator catches exceptions raised by
        # the handler (including our ValueError for an unknown tool name)
        # and converts them into an error CallToolResult rather than letting
        # them propagate.
        result = await handler(req)
        assert result.root.isError is True

    async def test_unsupported_content_type_skipped(self):
        @tool("weird", "d", {"x": str})
        async def weird_tool(args):
            return {"content": [{"type": "totally_unknown_type", "text": "x"}]}

        config = create_sdk_mcp_server(name="srv2", tools=[weird_tool])
        server = config["instance"]

        from mcp.types import CallToolRequest, CallToolRequestParams

        handler = server.request_handlers.get(CallToolRequest)
        req = CallToolRequest(
            method="tools/call",
            params=CallToolRequestParams(name="weird", arguments={"x": "test"}),
        )
        result = await handler(req)
        assert result.root.content == []

    async def test_binary_embedded_resource_skipped(self):
        @tool("res", "d", {"x": str})
        async def res_tool(args):
            return {
                "content": [
                    {"type": "resource", "resource": {"blob": "binarydata"}}
                ]
            }

        config = create_sdk_mcp_server(name="srv3", tools=[res_tool])
        server = config["instance"]

        from mcp.types import CallToolRequest, CallToolRequestParams

        handler = server.request_handlers.get(CallToolRequest)
        req = CallToolRequest(
            method="tools/call",
            params=CallToolRequestParams(name="res", arguments={"x": "test"}),
        )
        result = await handler(req)
        assert result.root.content == []

    async def test_list_tools(self):
        @tool("t1", "d1", {"a": str})
        async def t1(args):
            return {"content": []}

        config = create_sdk_mcp_server(name="srv4", tools=[t1])
        server = config["instance"]

        from mcp.types import ListToolsRequest

        handler = server.request_handlers.get(ListToolsRequest)
        result = await handler(ListToolsRequest(method="tools/list"))
        names = [t.name for t in result.root.tools]
