class FakeTransport:
    """Minimal fake Transport for Query tests."""

    def __init__(self, incoming_messages=None):
        self._incoming = incoming_messages or []
        self.written = []
        self._closed = False

    async def connect(self):
        pass

    async def write(self, data: str):
        self.written.append(data)

    async def read_messages(self):
        for msg in self._incoming:
            yield msg

    async def close(self):
        self._closed = True

    def is_ready(self):
        return True

    async def end_input(self):
        pass


class TestQueryInitialize:
    async def test_non_streaming_returns_none(self):
        transport = FakeTransport()
        q = Query(transport=transport, is_streaming_mode=False)
        result = await q.initialize()
        assert result is None

    async def test_skills_as_list_sent(self):
        transport = FakeTransport()
        q = Query(transport=transport, is_streaming_mode=True, skills=["skill1"])

        async def fake_send_control_request(request, timeout=60.0):
            return request

        q._send_control_request = fake_send_control_request  # type: ignore
        result = await q.initialize()
        assert result["skills"] == ["skill1"]

    async def test_skills_all_not_sent(self):
        transport = FakeTransport()
        q = Query(transport=transport, is_streaming_mode=True, skills="all")

        async def fake_send_control_request(request, timeout=60.0):
            return request

        q._send_control_request = fake_send_control_request  # type: ignore
        result = await q.initialize()
        assert "skills" not in result

    async def test_hooks_config_building(self):
        async def hook_cb(input_data, tool_use_id, context):
            return {}

        transport = FakeTransport()
        hooks = {"PreToolUse": [{"matcher": "Bash", "hooks": [hook_cb]}]}
        q = Query(transport=transport, is_streaming_mode=True, hooks=hooks)

        captured = {}

        async def fake_send_control_request(request, timeout=60.0):
            captured["request"] = request
            return request

        q._send_control_request = fake_send_control_request  # type: ignore
        await q.initialize()
        assert "PreToolUse" in captured["request"]["hooks"]
        assert q.hook_callbacks  # a callback was registered


