        # An empty (0-byte) session file is treated the same as "not found"
        # by the file resolver (_try_dir requires st_size > 0), so this
        # surfaces as FileNotFoundError rather than the "no messages to
        # fork" ValueError (which only triggers for a found, non-empty file
        # whose content parses to zero transcript entries).
        with pytest.raises(FileNotFoundError):
            fork_session(session_id)

    def test_up_to_message_id_not_found_raises(self, fake_projects_dir):
        session_id = str(uuid_mod.uuid4())
        proj_dir = fake_projects_dir / "myproj"
        proj_dir.mkdir()
        session_file = proj_dir / f"{session_id}.jsonl"
        msg_uuid = str(uuid_mod.uuid4())
        session_file.write_text(
            json.dumps(
                {
                    "type": "user",
                    "uuid": msg_uuid,
                    "sessionId": session_id,
                    "message": {"content": "hi"},
                }
            )
            + "\n"
        )
        with pytest.raises(ValueError, match="not found"):
            fork_session(session_id, up_to_message_id=str(uuid_mod.uuid4()))

    def test_successful_fork_creates_new_file(self, fake_projects_dir):
        session_id = str(uuid_mod.uuid4())
        proj_dir = fake_projects_dir / "myproj"
        proj_dir.mkdir()
        session_file = proj_dir / f"{session_id}.jsonl"
        msg_uuid = str(uuid_mod.uuid4())
        session_file.write_text(
            json.dumps(
                {
                    "type": "user",
                    "uuid": msg_uuid,
                    "sessionId": session_id,
                    "message": {"content": "hi"},
                }
            )
            + "\n"
        )
        result = fork_session(session_id)
        assert result.session_id != session_id
        fork_file = proj_dir / f"{result.session_id}.jsonl"
        assert fork_file.exists()

    def test_sidechain_filtering(self, fake_projects_dir):
        session_id = str(uuid_mod.uuid4())
        proj_dir = fake_projects_dir / "myproj"
        proj_dir.mkdir()
        session_file = proj_dir / f"{session_id}.jsonl"
        main_uuid = str(uuid_mod.uuid4())
        side_uuid = str(uuid_mod.uuid4())
        lines = [
            json.dumps(
                {
                    "type": "user",
                    "uuid": main_uuid,
                    "sessionId": session_id,
                    "message": {"content": "hi"},
                }
            ),
            json.dumps(
                {
                    "type": "user",
                    "uuid": side_uuid,
                    "sessionId": session_id,
                    "isSidechain": True,
                    "message": {"content": "side"},
                }
            ),
        ]
        session_file.write_text("\n".join(lines) + "\n")
        result = fork_session(session_id)
        fork_file = proj_dir / f"{result.session_id}.jsonl"
        content = fork_file.read_text()
        assert "side" not in content


