    async def test_timeout_not_retried(self):
        store = AsyncMock()

        async def slow_append(key, entries):
            await anyio.sleep(10)

        store.append.side_effect = slow_append
        on_error = AsyncMock()
        batcher = TranscriptMirrorBatcher(
            store=store,
            projects_dir="/proj/projects",
            on_error=on_error,
            send_timeout=0.01,
        )
        batcher.enqueue("/proj/projects/p/s.jsonl", [{"type": "x"}])
