class TestDisassembleBasic:
    def test_nop(self):
        mem = make_mem(0x00)
        inst = disassemble(mem, 0)
        assert inst.flow_type == FlowTypes.Continue
        assert str(inst) == 'nop'

    def test_illegal_opcode_raises(self):
        mem = make_mem(0xf1)
        with pytest.raises(IllegalInstructionError):
            disassemble(mem, 0)

    def test_illegal_second_byte_0x31(self):
        mem = make_mem(0x31, 0xff)
        with pytest.raises(IllegalInstructionError):
            disassemble(mem, 0)

    def test_illegal_second_byte_0x61(self):
        mem = make_mem(0x61, 0x00)
        with pytest.raises(IllegalInstructionError):
            disassemble(mem, 0)

    def test_illegal_second_byte_0x71(self):
        mem = make_mem(0x71, 0x01)
        with pytest.raises(IllegalInstructionError):
            disassemble(mem, 0)

    def test_saddr_alias_psw_set1(self):
        mem = make_mem(0x7a, 0x1e)
        inst = disassemble(mem, 0)
        assert str(inst) == 'ei'

    def test_saddr_alias_psw_clr1(self):
        mem = make_mem(0x7b, 0x1e)
        inst = disassemble(mem, 0)
        assert str(inst) == 'di'

    def test_callt_addr5(self):
        mem = make_mem(*([0x00] * 0x50))
        mem.contents[0x40] = 0x34
        mem.contents[0x41] = 0x12
        mem.contents[0] = 0b11000001
        inst = disassemble(mem, 0)
        assert inst.addr5 == 0x40
        assert inst.addr5target == 0x1234

    def test_dbnz_negative_reldisp_wraparound(self):
        mem = bytearray(0x10000)
        mem[0xFFFE] = 0x04
        mem[0xFFFF] = 0x20
        # can't append reldisp beyond memory; use different location
        m = Memory(bytes([0x04, 0x20, 0xFE]))
        inst = disassemble(m, 0)
        assert inst.reltarget == _resolve_rel(3, 0xFE)


