# ---------- Instruction class ----------

class TestInstructionClass:
    def test_init_defaults_none(self):
        inst = Instruction("nop")
        assert inst.saddr is None
        assert inst.imm8 is None
        assert inst.operands == ()

    def test_len_no_operands(self):
        inst = Instruction("nop", opcode=0x00, operands=())
        assert len(inst) == 1

    def test_len_multiple_operands(self):
        inst = Instruction("x", opcode=0x00, operands=(1, 2, 3))
        assert len(inst) == 4

    def test_all_bytes_empty_operands(self):
        inst = Instruction("nop", opcode=0x00, operands=())
        assert inst.all_bytes == [0x00]

    def test_referenced_addresses_none(self):
        inst = Instruction("nop", opcode=0x00, operands=())
        assert inst.referenced_addresses == []

    def test_referenced_addresses_multiple(self):
        inst = Instruction("x", saddr=0xfe20, addr16=0x1234, opcode=0, operands=())
        addrs = inst.referenced_addresses
        assert 0xfe20 in addrs
        assert 0x1234 in addrs

    def test_target_address_addr16(self):
        inst = Instruction("x", addr16=0x1234, opcode=0, operands=())
        assert inst.target_address == 0x1234

    def test_target_address_addr11(self):
        inst = Instruction("x", addr11=0x0800, opcode=0, operands=())
        assert inst.target_address == 0x0800

    def test_target_address_addr5target(self):
        inst = Instruction("x", addr5target=0x1000, opcode=0, operands=())
        assert inst.target_address == 0x1000

    def test_target_address_reltarget(self):
        inst = Instruction("x", reltarget=0x0500, opcode=0, operands=())
        assert inst.target_address == 0x0500

    def test_target_address_none(self):
        inst = Instruction("x", opcode=0, operands=())
        assert inst.target_address is None

    def test_to_string_symbol_replacement(self):
        inst = Instruction("mov a,{saddr}", saddr=0xfe20, opcode=0, operands=())
        symbols = {0xfe20: ('my_symbol', 'a comment')}
        assert inst.to_string(symbols) == "mov a,my_symbol"

    def test_to_string_no_symbol_hex_format(self):
        inst = Instruction("mov a,{saddr}", saddr=0xfe20, opcode=0, operands=())
        assert inst.to_string({}) == "mov a,0xfe20"

    def test_to_string_symbols_none_default(self):
        inst = Instruction("nop", opcode=0, operands=())
        assert inst.to_string() == "nop"

    def test_format_imm16_below_007f(self):
        inst = Instruction("movw ax,{imm16}", imm16=0x0010, opcode=0, operands=())
        result = inst.to_string({0x0010: ('sym', '')})
        assert result == "movw ax,0x0010"

    def test_format_imm16_in_symbols_above_007f(self):
        inst = Instruction("movw ax,{imm16}", imm16=0x1000, opcode=0, operands=())
        result = inst.to_string({0x1000: ('sym', '')})
        assert result == "movw ax,sym"

    def test_format_imm16_not_in_symbols(self):
        inst = Instruction("movw ax,{imm16}", imm16=0x1000, opcode=0, operands=())
        result = inst.to_string({})
        assert result == "movw ax,0x1000"

    def test_format_ext_address_in_symbols(self):
        inst = Instruction("x")
        result = inst._format_ext_address(0x1234, {0x1234: ('sym', '')})
        assert result == 'sym'

    def test_format_ext_address_not_in_symbols(self):
        inst = Instruction("x")
        result = inst._format_ext_address(0x1234, {})
        assert result == '0x1234'

    def test_multiple_placeholders_same_template(self):
        inst = Instruction("bt {saddr}.{bit},{reltarget}", saddr=0xfe20, bit=3,
                            reltarget=0x100, opcode=0, operands=())
        result = inst.to_string({})
        assert result == "bt 0xfe20.3,0x0100"


