class TestMemory:
    def test_init_padding(self):
        mem = Memory(bytes([1, 2, 3]))
        assert len(mem) == 0x10000
        assert mem[0] == 1
        assert mem[3] == 0

    def test_init_empty_rom(self):
        mem = Memory(b'')
        assert len(mem) == 0x10000

    def test_getitem_int(self):
        mem = Memory(bytes([9, 8, 7]))
        assert mem[1] == 8

    def test_getitem_slice(self):
        mem = Memory(bytes([1, 2, 3, 4]))
        result = mem[0:3]
        assert list(result) == [1, 2, 3]

    def test_getitem_slice_no_stop_raises(self):
        mem = Memory(bytes([1, 2, 3]))
        with pytest.raises(TypeError):
            mem[0:]

    def test_read_byte(self):
        mem = Memory(bytes([42]))
        assert mem.read_byte(0) == 42

    def test_read_word_normal(self):
        mem = Memory(bytes([0x34, 0x12]))
        assert mem.read_word(0) == 0x1234

    def test_read_word_wraparound(self):
        mem = Memory(bytes([0] * 0x10000))
        mem.contents[0xffff] = 0x34
        mem.contents[0x0000] = 0x12
        assert mem.read_word(0xffff) == 0x1234

    def test_set_instruction_overwrite_raises(self):
        mem = Memory(bytes([0x00, 0x00]))
        inst = Instruction("nop", opcode=0, operands=())
        mem.set_instruction(0, inst)
        with pytest.raises(Exception):
            mem.set_instruction(0, inst)

    def test_set_instruction_wraparound(self):
        mem = Memory(bytes([0] * 0x10000))
        inst = Instruction("x", opcode=0, operands=(1, 2))
        mem.set_instruction(0xfffe, inst)
        assert mem.is_instruction_start(0xfffe)
        assert mem.is_instruction_continuation(0xffff)
        assert mem.is_instruction_continuation(0x0000)

    def test_get_instruction_none(self):
        mem = Memory(bytes([0]))
        assert mem.get_instruction(0) is None

    def test_iter_instructions_none_found(self):
        mem = Memory(bytes([0, 0]))
        result = list(mem.iter_instructions())
        assert result == []

    def test_iter_instructions_with_address(self):
        mem = Memory(bytes([0] * 10))
        inst = Instruction("nop", opcode=0, operands=())
        mem.set_instruction(5, inst)
        result = list(mem.iter_instructions(address=0))
        assert result == [(5, inst)]
        result2 = list(mem.iter_instructions(address=6))
        assert result2 == []

    def test_set_vector_wraparound(self):
        mem = Memory(bytes([0] * 0x10000))
        mem.set_vector(0xffff)
        assert mem.is_vector_start(0xffff)
        assert mem.is_vector_continuation(0x0000)

    def test_get_vector_wraparound(self):
        mem = Memory(bytes([0] * 0x10000))
        mem.contents[0xffff] = 0x12
        mem.contents[0x0000] = 0x34
        assert mem.get_vector(0xffff) == 0x1234

    def test_iter_vectors_none(self):
        mem = Memory(bytes([0, 0]))
        assert list(mem.iter_vectors()) == []

    def test_set_data(self):
        mem = Memory(bytes([0]))
        mem.set_data(0)
        assert mem.is_data(0)

    def test_is_unknown_length_gt1(self):
        mem = Memory(bytes([0, 0, 0]))
        assert mem.is_unknown(0, length=3)
        mem.set_data(1)
        assert not mem.is_unknown(0, length=3)

    def test_is_unknown_wraparound(self):
        mem = Memory(bytes([0] * 0x10000))
        assert mem.is_unknown(0xfffe, length=3)

    def test_type_checks(self):
        mem = Memory(bytes([0, 0, 0, 0]))
        inst = Instruction("nop", opcode=0, operands=())
        mem.set_instruction(0, inst)
        mem.set_vector(2)
        assert mem.is_instruction_start(0)
        assert not mem.is_instruction_continuation(0)
        assert mem.is_vector_start(2)
        assert not mem.is_vector_continuation(2)
        assert mem.is_vector_continuation(3)

    def test_single_byte_or_start_of_multibyte(self):
        mem = Memory(bytes([0, 0]))
        inst = Instruction("nop", opcode=0, operands=(1,))
        mem.set_instruction(0, inst)
        assert mem.is_single_byte_or_start_of_multibyte(0)
        assert not mem.is_single_byte_or_start_of_multibyte(1)

    def test_is_continuation_of_multibyte_type(self):
        mem = Memory(bytes([0, 0, 0, 0]))
        inst = Instruction("x", opcode=0, operands=(1,))
        mem.set_instruction(0, inst)
        mem.set_vector(2)
        assert mem.is_continuation_of_multibyte_type(1)
        assert mem.is_continuation_of_multibyte_type(3)
        assert not mem.is_continuation_of_multibyte_type(0)

    def test_annotations_multiple(self):
        mem = Memory(bytes([0]))
        mem.annotate_entry_point(0)
        mem.annotate_jump_target(0)
        mem.annotate_call_target(0)
        mem.annotate_illegal_instruction(0)
        assert mem.is_entry_point(0)
        assert mem.is_jump_target(0)
        assert mem.is_call_target(0)
        assert mem.is_illegal_instruction(0)


