        mem.annotate_call_target(0)
        st = SymbolTable()
        st.generate_code_symbols(mem, 0)
        assert st.symbols[0][0] == 'sub_0000'

    def test_generate_code_symbols_call_target_not_instr_start(self):
        mem = Memory(bytes([0] * 10))
        mem.annotate_call_target(0)
        st = SymbolTable()
        st.generate_code_symbols(mem, 0)
        assert 0 not in st.symbols

    def test_generate_code_symbols_jump_and_entry(self):
        mem = Memory(bytes([0] * 10))
