        mem.set_instruction(0, inst)
        mem.annotate_jump_target(0)
        mem.annotate_entry_point(0)
        st = SymbolTable()
        st.generate_code_symbols(mem, 0)
        assert st.symbols[0][0] == 'lab_0000'

    def test_generate_data_symbols_saddr_always(self):
        mem = Memory(bytes([0] * 10))
        inst = Instruction("x", saddr=0xfe20, opcode=0, operands=())
        mem.set_instruction(0, inst)
        st = SymbolTable()
        st.generate_data_symbols(mem, 0)
        assert 0xfe20 in st.symbols

    def test_generate_data_symbols_addr16_jump_target_excluded(self):
        mem = Memory(bytes([0] * 10))
