# ---------- Printer ----------

class TestPrinter:
    def _build_simple(self):
        mem = Memory(bytes([0x00, 0x00]))
        inst = Instruction("nop", opcode=0, operands=())
        mem.set_instruction(0, inst)
        mem.set_data(1)
        st = SymbolTable()
        printer = Printer(mem, 0, 1, st)
        return printer, mem, st

    def test_print_listing_basic(self, capsys):
        printer, mem, st = self._build_simple()
        printer.print_listing()
        captured = capsys.readouterr()
        assert 'nop' in captured.out

    def test_print_listing_unknown_raises(self):
        mem = Memory(bytes([0, 0]))
        st = SymbolTable()
        printer = Printer(mem, 0, 1, st)
        with pytest.raises(NotImplementedError):
            printer.print_listing()

    def test_print_header(self, capsys):
        printer, mem, st = self._build_simple()
        printer.print_header()
        captured = capsys.readouterr()
        assert '.area CODE1' in captured.out
        assert '.org 0x0000' in captured.out

    def test_print_symbols_none_used(self, capsys):
        mem = Memory(bytes([0, 0]))
        inst = Instruction("nop", opcode=0, operands=())
        mem.set_instruction(0, inst)
        st = SymbolTable()
        printer = Printer(mem, 0, 1, st)
        printer.print_symbols()
        captured = capsys.readouterr()
        assert captured.out.strip() == ''

    def test_print_symbols_out_of_range_no_comment(self, capsys):
        mem = Memory(bytes([0] * 10))
        inst = Instruction("mov a,{saddr}", saddr=0x5000, opcode=0, operands=(0,))
        mem.set_instruction(0, inst)
        st = SymbolTable({0x5000: ('outside', '')})
        printer = Printer(mem, 0, 1, st)
        printer.print_symbols()
        captured = capsys.readouterr()
        assert 'outside' in captured.out
        assert '0x5000' in captured.out

    def test_print_symbols_out_of_range_with_comment(self, capsys):
        mem = Memory(bytes([0] * 10))
        inst = Instruction("mov a,{saddr}", saddr=0x5000, opcode=0, operands=(0,))
        mem.set_instruction(0, inst)
        st = SymbolTable({0x5000: ('outside', 'my comment')})
        printer = Printer(mem, 0, 1, st)
        printer.print_symbols()
        captured = capsys.readouterr()
        assert 'my comment' in captured.out

    def test_print_symbols_via_vectors(self, capsys):
        mem = Memory(bytes([0] * 20))
        mem.set_vector(0)
        mem.contents[0] = 0x00
        mem.contents[1] = 0x50
        st = SymbolTable({0x5000: ('vec_target', 'vector comment')})
        printer = Printer(mem, 0, 1, st)
        printer.print_symbols()
        captured = capsys.readouterr()
        assert 'vec_target' in captured.out

    def test_print_symbols_within_range_not_printed(self, capsys):
        mem = Memory(bytes([0] * 10))
        inst = Instruction("mov a,{saddr}", saddr=1, opcode=0, operands=(0,))
        mem.set_instruction(0, inst)
        st = SymbolTable({1: ('inside', '')})
        printer = Printer(mem, 0, 5, st)
        printer.print_symbols()
        captured = capsys.readouterr()
        assert 'inside' not in captured.out

    def test_print_blank_first_call(self):
        printer, mem, st = self._build_simple()
        assert printer.last_line_type is None
        printer.print_blank(0)
        assert printer.last_line_type is not None

    def test_print_blank_type_change_no_symbol(self, capsys):
        printer, mem, st = self._build_simple()
        printer.print_blank(0)
        capsys.readouterr()
        printer.print_blank(1)
        captured = capsys.readouterr()
        assert captured.out == '\n'

    def test_print_blank_type_change_with_symbol(self, capsys):
        printer, mem, st = self._build_simple()
        st.symbols[1] = ('sym', '')
        printer.print_blank(0)
        capsys.readouterr()
        printer.print_blank(1)
        captured = capsys.readouterr()
        assert captured.out == ''

    def test_print_label_no_symbol(self, capsys):
        printer, mem, st = self._build_simple()
        printer.print_label(0)
        captured = capsys.readouterr()
        assert captured.out == ''

    def test_print_label_with_symbol(self, capsys):
