def test_iterate_mapping_candidates_order():
    schema = {Extra: str, int: str, 'literal': str}
    compiled = {k: (None, None) for k in schema}
    result = list(_iterate_mapping_candidates(compiled))
    keys = [k for k, _ in result]
    # 'literal' (a plain value) has highest priority, followed by Extra
    # (callable) and finally int (a type/class), based on the sort
    # priority defined in _compile_itemsort.
    assert keys[0] == 'literal'
    assert keys.index(Extra) < keys.index(int)


