        result = process_wohand(b"\x01", None)
        assert result == {"switchMode": None, "isOn": None, "battery": None}

    def test_valid_data_switch_on(self):
        # switchMode bit set, isOn bit not set -> isOn True
        data = bytes([0x00, 0b10000000, 0b00000010])
        result = process_wohand(data, None)
        assert result["switchMode"] is True
        assert result["isOn"] is True
        assert result["battery"] == 2

    def test_valid_data_switch_off_mode(self):
        data = bytes([0x00, 0b00000000, 0b00000010])
        result = process_wohand(data, None)
        assert result["switchMode"] is False
        assert result["isOn"] is False


