class TestParam:
    def test_call_spec(self):
        p = Param(1, 2, arg_names=("a", "b"))
        assert p.call_spec == {"a": 1, "b": 2}

    def test_str_with_id(self):
        p = Param(1, arg_names=("a",), id="myid")
        assert str(p) == "myid"

    def test_str_without_id(self):
        p = Param(1, arg_names=("a",))
        assert str(p) == "a=1"

    def test_copy(self):
        p = Param(1, arg_names=("a",), id="x", tags=["t1"])
        p2 = p.copy()
        assert p2 == p
        assert p2 is not p

    def test_update(self):
        p1 = Param(1, arg_names=("a",), tags=["t1"])
        p2 = Param(2, arg_names=("b",), tags=["t2"])
        p1.update(p2)
        assert p1.args == (1, 2)
        assert p1.arg_names == ("a", "b")
        assert p1.tags == ["t1", "t2"]

    def test_eq_with_dict(self):
        p = Param(1, arg_names=("a",))
        assert p == {"a": 1}

    def test_eq_notimplemented(self):
        p = Param(1, arg_names=("a",))
        assert (p == 5) is False

    def test_eq_param_diff(self):
        p1 = Param(1, arg_names=("a",))
        p2 = Param(2, arg_names=("a",))
        assert p1 != p2


class TestParametrizeDecorator:
    def test_single_arg_simple_list(self):
        def f():
            pass

        deco = parametrize_decorator("x", [1, 2, 3])
        deco(f)
        assert len(f.parametrize) == 3
        assert f.parametrize[0].call_spec == {"x": 1}

    def test_multi_arg(self):
        def f():
            pass

        deco = parametrize_decorator("x,y", [(1, "a"), (2, "b")])
        deco(f)
        assert f.parametrize[0].call_spec == {"x": 1, "y": "a"}

    def test_with_param_instances(self):
        def f():
            pass

        p = Param(1, 2, arg_names=("x", "y"))
        deco = parametrize_decorator(["x", "y"], p)
        deco(f)
        assert f.parametrize[0].call_spec == {"x": 1, "y": 2}

    def test_ids_and_tags(self):
        def f():
            pass

        deco = parametrize_decorator("x", [1, 2], ids=["one", "two"], tags=[["t1"], ["t2"]])
        deco(f)
        assert f.parametrize[0].id == "one"
        assert f.parametrize[0].tags == ["t1"]

    def test_arg_names_as_string_with_commas(self):
        def f():
            pass

        deco = parametrize_decorator(" x , y ", [(1, 2)])
        deco(f)
        assert f.parametrize[0].arg_names == ("x", "y")

    def test_stacked_decorators(self):
        def f():
            pass

        deco1 = parametrize_decorator("x", [1, 2])
        deco1(f)
        deco2 = parametrize_decorator("y", [3, 4])
        deco2(f)
        assert len(f.parametrize) == 4


