class TestLocalizeImageUrls:
    def test_img_tag_replaced(self):
        html = '<img class="thumb1" src="https://cdn.example.com/pic.png" />'
        result_html, mapping = srv._localize_image_urls(html, "design1")
        assert "https://cdn.example.com/pic.png" not in result_html
        assert "./assets/slices/thumb1.png" in result_html
        assert mapping["./assets/slices/thumb1.png"] == "https://cdn.example.com/pic.png"

    def test_css_url_replaced(self):
        html = '<style>.bg1 { background: url(https://cdn.example.com/bg.jpg); }</style>'
        result_html, mapping = srv._localize_image_urls(html, "design1")
        assert "https://cdn.example.com/bg.jpg" not in result_html
        assert any("bg1" in k for k in mapping.keys())

    def test_duplicate_url_reuses_same_local_path(self):
        html = ('<img class="a" src="https://cdn.example.com/same.png" />'
                '<img class="b" src="https://cdn.example.com/same.png" />')
        result_html, mapping = srv._localize_image_urls(html, "design1")
        # Should only have one entry mapping to that URL
        matching_paths = [k for k, v in mapping.items() if v == "https://cdn.example.com/same.png"]
        assert len(matching_paths) == 1

    def test_no_remote_url_no_change(self):
        html = '<div class="box"></div>'
        result_html, mapping = srv._localize_image_urls(html, "design1")
        assert result_html == html
        assert mapping == {}

    def test_svg_extension_detected(self):
        html = '<img class="icon1" src="https://cdn.example.com/icon.svg" />'
        result_html, mapping = srv._localize_image_urls(html, "design1")
        assert any(v.endswith(".svg") for v in [k for k in mapping]) or "icon1.svg" in result_html


