class TestStringRecursiveParse:
    def test_plain_string_not_json(self):
        assert string_recursive_parse("hello") == "hello"

    def test_json_string_object(self):
        result = string_recursive_parse('{"a": 1}')
        assert result == {"a": 1}

    def test_json_string_array(self):
        result = string_recursive_parse('[1, 2, 3]')
        assert result == [1, 2, 3]

    def test_invalid_json_string_starting_with_brace(self):
        result = string_recursive_parse("{not valid json")
        assert result == "{not valid json"

    def test_dict_with_nested_json_string(self):
        data = {"key": '{"nested": true}'}
        result = string_recursive_parse(data)
        assert result == {"key": {"nested": True}}

    def test_list_with_nested_json_string(self):
        data = ['{"a": 1}', "plain"]
        result = string_recursive_parse(data)
        assert result == [{"a": 1}, "plain"]

    def test_max_depth_reached(self):
        # deeply nested list to trigger max depth cutoff
        nested = '{"a": 1}'
        for _ in range(15):
            nested = orjson_dumps_wrap(nested)
        result = string_recursive_parse(nested)
        # should not raise, and depth limiting prevents infinite recursion
        assert result is not None

    def test_non_dict_list_str(self):
        assert string_recursive_parse(42) == 42
        assert string_recursive_parse(None) is None


def orjson_dumps_wrap(value):
    """Helper to wrap a string value into a JSON string representation."""
    import orjson

    return orjson.dumps(value).decode("utf-8")


