class TestReplaceRoutinePlaceholders:
    def test_replace_serial_placeholder(self):
        device = make_device(serial="XYZ123")
        obj = {"key": "ALEXA_CURRENT_DSN"}
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "XYZ123"

    def test_replace_device_type_placeholder(self):
        device = make_device(device_type="ABC456")
        obj = {"key": "ALEXA_CURRENT_DEVICE_TYPE"}
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "ABC456"

    def test_replace_trigger_serial_placeholder(self):
        device = make_device(serial="TRIG1")
        obj = {
            "key": "<$Trigger.Alexa.Trigger.Alarms.NotificationStopped.$.payload.object.device.deviceSerialNumber$>"
        }
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "TRIG1"

    def test_replace_trigger_device_type_placeholder(self):
        device = make_device(device_type="TRIGTYPE")
        obj = {
            "key": "<$Trigger.Alexa.Trigger.Alarms.NotificationStopped.$.payload.object.device.productId$>"
        }
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "TRIGTYPE"

    def test_no_placeholder_unchanged(self):
        device = make_device()
        obj = {"key": "plain value"}
        result = replace_routine_placeholders(obj, device)
        assert result["key"] == "plain value"

    def test_nested_dict_and_list(self):
        device = make_device(serial="NESTED1")
        obj = {
            "outer": {
                "inner": ["ALEXA_CURRENT_DSN", "unchanged"],
            }
        }
        result = replace_routine_placeholders(obj, device)
        assert result["outer"]["inner"][0] == "NESTED1"
        assert result["outer"]["inner"][1] == "unchanged"


