class TestLocalizeImageUrls:
    def test_no_remote_urls(self):
        html = "<div>No images here</div>"
        result, mapping = lms._localize_image_urls(html, "design")
        assert result == html
        assert mapping == {}

    def test_img_tag_replacement(self):
        html = '<img class="icon1" src="https://cdn.example.com/img.png" />'
        result, mapping = lms._localize_image_urls(html, "design")
        assert "https://cdn.example.com/img.png" not in result
        assert "./assets/slices/icon1.png" in result
        assert mapping["./assets/slices/icon1.png"] == "https://cdn.example.com/img.png"

    def test_css_background_url_replacement(self):
        html = (
            "<style>.bg1 { background: url(https://cdn.example.com/bg.png); }</style>"
            '<div class="bg1"></div>'
        )
        result, mapping = lms._localize_image_urls(html, "design")
        assert "https://cdn.example.com/bg.png" not in result
        assert any("bg1" in path for path in mapping.keys())

    def test_duplicate_url_reuses_same_local_path(self):
        html = (
            '<img class="icon1" src="https://cdn.example.com/img.png" />'
            '<img class="icon2" src="https://cdn.example.com/img.png" />'
        )
        result, mapping = lms._localize_image_urls(html, "design")
        assert len(mapping) == 1  # same URL should be deduplicated

    def test_extension_detection(self):
        html = '<img class="icon1" src="https://cdn.example.com/img.jpg" />'
        result, mapping = lms._localize_image_urls(html, "design")
        local_paths = list(mapping.keys())
        assert local_paths[0].endswith(".jpg")

    def test_unknown_extension_defaults_to_png(self):
        html = '<img class="icon1" src="https://cdn.example.com/img" />'
        result, mapping = lms._localize_image_urls(html, "design")
        local_paths = list(mapping.keys())
        assert local_paths[0].endswith(".png")

    def test_loop_suffix_sanitized(self):
        html = '<img class="item-0" src="https://cdn.example.com/img.png" />'
        result, mapping = lms._localize_image_urls(html, "design")
        local_paths = list(mapping.keys())
        assert "item.png" in local_paths[0] or "item" in local_paths[0]


