from nox._resolver import CycleError, lazy_stable_topo_sort  # noqa: E402


class TestLazyStableTopoSort:
    def test_basic_sort(self):
        deps = {
            "a": ["c", "b"],
            "b": [],
            "c": [],
            "d": ["e"],
            "e": ["c"],
            "root": ["a", "d"],
        }
        result = list(lazy_stable_topo_sort(deps, "root", drop_root=False))
        assert result == ["c", "b", "a", "e", "d", "root"]

    def test_drop_root_default(self):
        deps = {"a": [], "root": ["a"]}
        result = list(lazy_stable_topo_sort(deps, "root"))
        assert result == ["a"]

    def test_no_dependencies(self):
        deps = {"root": []}
        result = list(lazy_stable_topo_sort(deps, "root"))
        assert result == []

    def test_cycle_detected(self):
        deps = {"a": ["b"], "b": ["a"], "root": ["a"]}
        with pytest.raises(CycleError):
            list(lazy_stable_topo_sort(deps, "root"))

    def test_self_cycle(self):
        deps = {"a": ["a"], "root": ["a"]}
        with pytest.raises(CycleError):
            list(lazy_stable_topo_sort(deps, "root"))


