from nox._parametrize import Param, parametrize_decorator, update_param_specs  # noqa: E402


class TestParam:
    def test_call_spec(self):
        p = Param(1, 2, arg_names=["a", "b"])
        assert p.call_spec == {"a": 1, "b": 2}

    def test_str_with_id(self):
        p = Param(1, arg_names=["a"], id="myid")
        assert str(p) == "myid"

    def test_str_without_id(self):
        p = Param(1, arg_names=["a"])
        assert str(p) == "a=1"

    def test_copy(self):
        p = Param(1, arg_names=["a"], id="x", tags=["t1"])
        p2 = p.copy()
        assert p2 == p
        assert p2 is not p

    def test_update(self):
        p1 = Param(1, arg_names=["a"], tags=["t1"])
        p2 = Param(2, arg_names=["b"], tags=["t2"])
        p1.update(p2)
        assert p1.args == (1, 2)
        assert p1.arg_names == ("a", "b")
        assert p1.tags == ["t1", "t2"]

    def test_eq_with_dict(self):
        p = Param(1, arg_names=["a"])
        assert p == {"a": 1}

    def test_eq_not_implemented(self):
        p = Param(1, arg_names=["a"])
        assert p.__eq__(42) is NotImplemented

    def test_eq_different_param(self):
        p1 = Param(1, arg_names=["a"], id="x")
        p2 = Param(2, arg_names=["a"], id="x")
        assert p1 != p2


class TestParametrizeDecorator:
    def test_single_arg_name_list(self):
        deco = parametrize_decorator("x", [1, 2, 3])

        def f():
            pass

        result = deco(f)
        assert len(result.parametrize) == 3
        assert result.parametrize[0].args == (1,)

    def test_multiple_arg_names(self):
        deco = parametrize_decorator("x,y", [(1, 2), (3, 4)])

        def f():
            pass

        result = deco(f)
        assert len(result.parametrize) == 2
        assert result.parametrize[0].call_spec == {"x": 1, "y": 2}

    def test_with_ids(self):
        deco = parametrize_decorator("x", [1, 2], ids=["one", "two"])

        def f():
            pass

        result = deco(f)
        assert result.parametrize[0].id == "one"
        assert result.parametrize[1].id == "two"

    def test_with_tags(self):
        deco = parametrize_decorator("x", [1, 2], tags=[["t1"], ["t2"]])

        def f():
            pass

        result = deco(f)
        assert result.parametrize[0].tags == ["t1"]

    def test_single_param_instance(self):
        param = Param(1, arg_names=["x"])
        deco = parametrize_decorator("x", param)

        def f():
            pass

        result = deco(f)
        assert len(result.parametrize) == 1

    def test_multi_arg_names_as_tuple(self):
        deco = parametrize_decorator(("x", "y"), [(1, 2)])

        def f():
            pass

        result = deco(f)
        assert result.parametrize[0].call_spec == {"x": 1, "y": 2}

    def test_stacking_decorators(self):
        deco1 = parametrize_decorator("x", [1, 2])
        deco2 = parametrize_decorator("y", [10, 20])

        def f():
            pass

        f1 = deco1(f)
        f2 = deco2(f1)
        # Should be a cartesian combination: 2 * 2 = 4
        assert len(f2.parametrize) == 4


class TestUpdateParamSpecs:
    def test_no_existing_specs(self):
        new_specs = [Param(1, arg_names=["a"])]
        result = update_param_specs(None, new_specs)
        assert result == new_specs

    def test_combine_specs(self):
        old_specs = [Param(1, arg_names=["a"])]
        new_specs = [Param(2, arg_names=["b"])]
        result = update_param_specs(old_specs, new_specs)
        assert len(result) == 1
        assert result[0].call_spec == {"a": 1, "b": 2}

    def test_combine_multiple(self):
        old_specs = [Param(1, arg_names=["a"]), Param(2, arg_names=["a"])]
        new_specs = [Param(10, arg_names=["b"]), Param(20, arg_names=["b"])]
        result = update_param_specs(old_specs, new_specs)
        assert len(result) == 4


