class TestCall:
    def test_call_generates_call_spec(self):
        def f(session, x):
            pass

        func = Func(f)
        param = ParamCls(5, arg_names=["x"])
        call = Call(func, param)
        assert call.call_spec == {"x": 5}

    def test_call_extracts_python_from_param_spec(self):
        def f(session):
            pass

        func = Func(f, python=None)
        param = ParamCls("3.9", arg_names=["python"])
        call = Call(func, param)
        assert call.python == "3.9"
        # python should be removed from call_spec
        assert "python" not in call.call_spec

    def test_call_keeps_python_arg_if_in_signature(self):
        def f(session, python):
            pass

        func = Func(f, python=None)
        param = ParamCls("3.9", arg_names=["python"])
        call = Call(func, param)
        # python arg is a normal argument, so python attribute stays None
        assert call.python is None
        assert call.call_spec == {"python": "3.9"}

    def test_generate_calls(self):
        def f(session, x):
            pass

        func = Func(f)
        params = [ParamCls(1, arg_names=["x"]), ParamCls(2, arg_names=["x"])]
        calls = Call.generate_calls(func, params)
        assert len(calls) == 2

    def test_call_repr(self):
        def f(session, x):
            pass

        func = Func(f)
        param = ParamCls(1, arg_names=["x"], id="myid")
        call = Call(func, param)
        assert "myid" in repr(call)

    def test_call_invocation_updates_kwargs(self):
        def f(session, x=None):
            return x

        func = Func(f)
        param = ParamCls(42, arg_names=["x"])
        call = Call(func, param)
        result = call(session=None)
        assert result == 42


