from nox.workflow import execute  # noqa: E402


class TestWorkflowExecute:
    def test_execute_all_functions_run(self):
        calls = []

        def f1(**kwargs):
            calls.append("f1")

        def f2(prev, **kwargs):
            calls.append("f2")

        result = execute([f1, f2], argparse.Namespace())
        assert calls == ["f1", "f2"]
        assert result == 0

    def test_execute_returns_int_early(self):
        calls = []

        def f1(**kwargs):
            calls.append("f1")
            return 5

        def f2(prev, **kwargs):
            calls.append("f2")

        result = execute([f1, f2], argparse.Namespace())
        assert result == 5
        assert calls == ["f1"]

    def test_execute_keyboard_interrupt(self):
        def f1(**kwargs):
            raise KeyboardInterrupt

        result = execute([f1], argparse.Namespace())
        assert result == 130

    def test_execute_empty_workflow(self):
        result = execute([], argparse.Namespace())
        assert result == 0


